"  .tabs button{font-family:var(--ui); font-size:12px; font-weight:600; color:var(--muted); background:transparent; border:0;\n"
"    padding:6px 12px; border-radius:5px; cursor:pointer}\n"
"  .tabs button.active{background:var(--accent-2); color:#fff}\n"
"  .panel{display:none; flex:1; min-height:0; flex-direction:column}\n"
"  .panel.active{display:flex}\n"
"  .controls{display:flex; align-items:center; gap:9px 14px; flex-wrap:wrap; padding:9px 12px; border:1px solid var(--border);\n"
"    border-radius:var(--r-sm); background:#0f1826; flex:0 0 auto; margin-bottom:8px; font-family:var(--mono); font-size:11.5px; color:var(--muted)}\n"
"  .controls + .controls{margin-top:-4px}\n"
"  .controls label{display:inline-flex; align-items:center; gap:6px; color:var(--muted)}\n"
"  .controls select,.controls input[type=number]{width:auto; font-family:var(--mono); font-size:12px; padding:5px 7px}\n"
"  .controls input[type=number]{width:72px}\n"
"  .controls .axis-check{font-weight:700}\n"
"  .values,.stats{font-family:var(--mono); font-size:11.5px; color:var(--muted); padding:8px 2px 0; display:flex; gap:16px; flex-wrap:wrap; flex:0 0 auto}\n"
"  .values .val,.stats b{color:var(--text)}\n"
"\n"
"  /* ---------- settings ---------- */\n"
"  .settings2{display:grid; grid-template-columns:190px 1fr; gap:14px; height:100%}\n"
"  .snav{display:flex; flex-direction:column; gap:2px}\n"
"  .snav .sitem{display:flex; align-items:center; gap:10px; padding:9px 11px; border-radius:7px; color:var(--muted);\n"
"    font-size:13px; font-weight:600; cursor:pointer; background:transparent; border:0; text-align:left; width:100%}\n"
"  .snav .sitem svg{width:16px; height:16px; stroke:currentColor; fill:none; stroke-width:1.8; flex:0 0 auto}\n"
"  .snav .sitem:hover{background:var(--panel2); color:var(--text)}\n"
"  .snav .sitem.active{background:var(--accent-2); color:#fff}\n"
"  .spane{min-width:0; overflow:auto; display:flex; flex-direction:column; gap:13px}\n"
"  .spane .card{flex:0 0 auto}\n"
"  .card.sg-hide{display:none}\n"
"\n"
"  .pwrow{display:flex; gap:8px; margin-top:8px}\n"
"  .pwrow input{flex:1}\n"
"  .pwrow button{flex:0 0 auto}\n"
"  .wifi-net-list{margin-top:8px}\n"
"  #wifi-ssid,#wifi-user,#rec-name,#stream-ip,#stream-port,#marker-note,#ota-url,#ota-cfid,#ota-cfsecret{margin-top:8px}\n"
"  .rec-row{display:flex; align-items:center; gap:10px; padding:8px 2px; border-bottom:1px solid var(--border); font-size:12.5px}\n"
"  .rec-row:last-child{border-bottom:0}\n"
"  .rec-row .rec-name{flex:1; min-width:0}\n"
"  .rec-row .rec-actions{display:flex; gap:7px; flex:0 0 auto}\n"
"  .rec-row .rec-actions button{font-size:11.5px; padding:5px 9px; border-radius:6px}\n"
"\n"
"  /* ---------- recordings list (song rows) ---------- */\n"
"  .song{display:flex; align-items:center; gap:11px; padding:9px 8px; border-radius:8px; border:1px solid transparent;\n"
"    transition:.12s; cursor:pointer}\n"
"  .song:hover{background:var(--panel2); border-color:var(--border)}\n"
"  .song .cover{width:40px; height:40px; border-radius:6px; flex:0 0 auto; background:var(--bg2); border:1px solid var(--border); display:block}\n"
"  .song-main{min-width:0; flex:1}\n"
"  .song-title{font-weight:600; font-size:13px}\n"
"  .song-title .nm{display:block; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}\n"
"  .song-sub{color:var(--muted); font-size:11.5px; font-family:var(--mono); margin-top:2px; display:flex; gap:5px 10px; flex-wrap:wrap; align-items:center}\n"
"  .csv-txt{color:var(--faint)}\n"
"  .csv-txt.on{color:#63d67d}\n"
"  .dots{width:28px; height:28px; padding:0; justify-content:center; border-radius:6px; border:1px solid transparent;\n"
"    background:transparent; color:var(--muted); font-size:16px; flex:0 0 auto}\n"
"  .dots:hover{background:var(--panel3); color:var(--text); border-color:transparent}\n"
"  .song > .mini{flex:0 0 auto}\n"
"  .mini{white-space:nowrap}\n"
"  .chip{display:inline-flex; align-items:center; font-size:10.5px; font-weight:600; padding:2px 7px; border-radius:99px; font-family:var(--mono); white-space:nowrap}\n"
"  .chip.has{background:#12331d; color:#63d67d; border:1px solid #1d5c2f}\n"
"  .chip.busy{background:#132a3f; color:#8ac6ff; border:1px solid #235078}\n"
"  .chip.paused{background:#3a2e12; color:#e0b752; border:1px solid #6b5220}\n"
"  .chip.no{background:var(--panel2); color:var(--faint); border:1px solid var(--border)}\n"
"\n"
"  /* ---------- quick-actions menu ---------- */\n"
"  .menu{position:fixed; z-index:60; min-width:210px; background:var(--panel); border:1px solid var(--border2);\n"
"    border-radius:9px; box-shadow:var(--sh2); padding:6px; display:none}\n"
"  .menu.open{display:block}\n"
"  .menu button{display:flex; align-items:center; gap:10px; width:100%; justify-content:flex-start; background:transparent;\n"
"    border:0; color:var(--text); padding:8px 10px; border-radius:6px; font-size:13px; font-weight:500}\n"
"  .menu button:hover{background:var(--panel2); border-color:transparent}\n"
"  .menu button.danger{color:#ff8f88; background:transparent}\n"
"  .menu button.danger:hover{background:#3a1414}\n"
"  .menu .gi{width:18px; text-align:center; flex:0 0 auto}\n"
"  .menu .mdiv{height:1px; background:var(--border); margin:5px 4px}\n"
"\n"
"  /* ---------- detail sheet ---------- */\n"
"  .backdrop{position:fixed; inset:0; z-index:70; background:rgba(4,7,12,.6); display:none; justify-content:center; align-items:flex-start; padding:24px 16px; overflow:auto}\n"
"  .backdrop.open{display:flex}\n"
"  .sheet{width:min(680px,100%); background:var(--panel); border:1px solid var(--border2); border-radius:12px; box-shadow:var(--sh2); overflow:hidden}\n"
"  .sheet-head{display:flex; align-items:center; gap:12px; padding:14px 16px; border-bottom:1px solid var(--border)}\n"
"  .sheet-head .cover{width:58px; height:58px; border-radius:8px; flex:0 0 auto; background:var(--bg2); border:1px solid var(--border)}\n"
"  .sheet-head h3{font-size:15px; display:flex; align-items:center; gap:8px}\n"
"  .sheet-head .when{color:var(--muted); font-size:12px; font-family:var(--mono); margin-top:3px}\n"
"  .sheet-x{margin-left:auto; width:32px; height:32px; padding:0; justify-content:center; font-size:20px; background:transparent; border:1px solid transparent; color:var(--muted)}\n"
"  .sheet-x:hover{background:var(--panel2); color:var(--text); border-color:transparent}\n"
"  .sheet-body{padding:14px 16px; max-height:70vh; overflow:auto}\n"
"  .slabel{font-family:var(--mono); font-size:10.5px; text-transform:uppercase; letter-spacing:.06em; color:var(--faint); margin:14px 0 8px}\n"
"  .slabel:first-child{margin-top:0}\n"
"  .meta{display:grid; grid-template-columns:repeat(2,1fr); gap:0 18px}\n"
"  .meta .m{display:flex; justify-content:space-between; gap:10px; padding:5px 0; border-bottom:1px solid var(--border); font-size:12.5px}\n"
"  .meta .mk{color:var(--muted)}\n"
"  .meta .mv{font-family:var(--mono); text-align:right}\n"
"  .files{display:flex; flex-direction:column; gap:7px}\n"
"  .filerow{display:flex; align-items:center; gap:10px; font-family:var(--mono); font-size:12px}\n"
"  .filerow .fn{flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:var(--text)}\n"
"  .filerow .fs{color:var(--muted)}\n"
"  .btnlink{font-family:var(--ui); font-size:11.5px; font-weight:600; color:var(--text); border:1px solid var(--border2);\n"
"    background:var(--panel3); padding:5px 10px; border-radius:6px; text-decoration:none; white-space:nowrap}\n"
"  .btnlink:hover{background:#2b3d5c; border-color:var(--accent)}\n"
"  .logbox{font-family:var(--mono); font-size:11px; background:var(--bg2); border:1px solid var(--border); border-radius:7px;\n"
"    padding:9px; color:var(--muted); white-space:pre-wrap; word-break:break-word; max-height:200px; overflow:auto}\n"
"  .sheet-actions{display:flex; gap:9px; flex-wrap:wrap; margin-top:16px}\n"
"\n"
"  /* ---------- toast ---------- */\n"
"  .toast{position:fixed; left:50%; bottom:26px; transform:translateX(-50%) translateY(20px); z-index:90;\n"
"    background:var(--panel3); border:1px solid var(--border2); color:var(--text); font-size:13px; padding:10px 16px;\n"
"    border-radius:9px; box-shadow:var(--sh2); opacity:0; pointer-events:none; transition:.2s}\n"
"  .toast.show{opacity:1; transform:translateX(-50%) translateY(0)}\n"
"\n"
"  /* ---------- accel chart fullscreen ---------- */\n"
"  .card.chart-fullscreen{position:fixed; inset:0; z-index:80; border-radius:0; margin:0}\n"
"  .card.chart-fullscreen .graphbox{min-height:0}\n"
"\n"
"  /* ---------- ota drop ---------- */\n"
"  #ota-drop.drop-hot{outline:2px dashed var(--accent); outline-offset:3px; border-radius:7px}\n"
"\n"
"  /* analyze fullscreen: native Fullscreen API fills the screen; the CSS overlay\n"
"     (.an-fs) is the fallback and also fills the fullscreen viewport. */\n"
"  #an-shell:fullscreen, #an-shell:-webkit-full-screen{background:var(--bg2); padding:12px; display:flex; flex-direction:column}\n"
"  .an-fs-hint{display:none; padding:6px 4px 0; font-family:var(--mono); font-size:11px; color:var(--faint); flex:0 0 auto}\n"
"\n"
"  /* ---------- mobile ---------- */\n"
"  @media (max-width:760px){\n"
"    .navtabs{display:none}\n"
"    .bottomnav{display:flex}\n"
"    .appbody{padding:8px}\n"
"    .sbar{gap:10px; font-size:11px}\n"
"    .sbar .sbar-model{display:none}\n"
"    .brand-text{display:none}\n"
"    .sb-wifi-ssid{display:none}\n"
"    .dash{display:flex; flex-direction:column; height:auto; gap:12px}\n"
"    .d-act{height:200px; flex:0 0 auto}\n"
"    .d-ble{height:420px; flex:0 0 auto}\n"
"    .an2{grid-template-columns:1fr}\n"
"    .settings2{grid-template-columns:1fr}\n"
"    .snav{display:none}\n"
"    .card.sg-hide{display:flex}\n"
"    .meta{grid-template-columns:1fr}\n"
"    #tab-analyze.apptab.active{height:auto}\n"
"    #an-views{min-height:420px}\n"
"    #an-shell.an-fs #an-views{min-height:0}\n"
"    #an-shell.an-fs .an-fs-hint{display:block}\n"
"    /* Analyze header stacks cleanly on mobile: source toggle, then mode toggle,\n"
"       then a compact status + Hide + Fullscreen row (the one-row desktop layout\n"
"       jams up when narrow). */\n"
"    .an-header{gap:8px}\n"
"    .an-header > .seg-toggle{flex:0 0 auto; align-self:flex-start}\n"
"    #an-browser-ctrls{flex-basis:100%; gap:8px 10px}\n"
"    #an-browser-ctrls > .tabs{flex-basis:100%; justify-content:space-between}\n"
"    #an-browser-ctrls > .sp{display:none}\n"
"    #an-browser-ctrls > .an-status{order:2; flex:0 1 auto; min-width:0; overflow:hidden; text-overflow:ellipsis}\n"
"    #an-browser-ctrls > button{order:3; flex:0 0 auto}\n"
"    /* keep the status short so it shares a row with the two buttons */\n"
"    .an-status #an-text, .an-status #drops-text, .an-status #fs-text{display:none}\n"
"  }\n"
"  @media (prefers-reduced-motion:reduce){ *{animation:none !important; transition:none !important} }\n"
"</style>\n"
"</head>\n"
"<body>\n"
"\n"
"<header class=\"apphead\">\n"
"  <div class=\"sbar\">\n"
"    <span class=\"brand\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 32 32\"><rect width=\"32\" height=\"32\" rx=\"7\" fill=\"#0f1420\"/><polyline points=\"2,17 8,17 11,8 15,26 19,6 23,20 26,17 30,17\" fill=\"none\" stroke=\"#58a6ff\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg><span class=\"brand-text\"> BTScanner</span></span>\n"
"    <span class=\"si sbar-model\">IIS3DWB</span>\n"
"    <span class=\"sp\"></span>\n"
"    <span class=\"si\"><span class=\"dot\" id=\"live-dot\"></span><span id=\"live-text\">connecting…</span></span>\n"
"    <span class=\"si\" id=\"sb-wifi\" title=\"Wi-Fi signal\"><span class=\"wb\" id=\"sb-wifi-bars\"><i class=\"off\"></i><i class=\"off\"></i><i class=\"off\"></i><i class=\"off\"></i></span><span class=\"sb-wifi-ssid\" id=\"sb-wifi-ssid\"></span></span>\n"
"    <span class=\"si\" id=\"sb-clock\" title=\"Device clock\">--:-- UTC</span>\n"
"    <span class=\"si\"><span class=\"dot\" id=\"chg-dot\"></span><span id=\"chg-status-text\">–</span></span>\n"
"    <span class=\"si batt\" id=\"sb-batt\"><span class=\"cell\"><i id=\"sb-batt-fill\"></i></span><span id=\"batt-estimate-text\">–</span></span>\n"
"    <span class=\"si\" style=\"display:none\"><span id=\"chg-batt-text\"></span></span>\n"
"    <span class=\"si\"><span class=\"dot\" id=\"sd-dot\"></span><span id=\"sd-status-text\">SD –</span>\n"
"      <button class=\"sb-btn\" id=\"sd-remount-btn\" onclick=\"remountSd(this)\" style=\"display:none\">Remount</button></span>\n"
"  </div>\n"
"  <nav class=\"navtabs\">\n"
"    <button data-nav=\"dashboard\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 13h4l2-8 4 14 3-9 2 3h4\"/></svg>Dashboard</button>\n"
"    <button data-nav=\"analyze\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 12h3l2-7 3 12 3-9 2 4h5M3 20h18\"/></svg>Analyze</button>\n"
"    <button data-nav=\"recordings\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16M4 12h16M4 18h10\"/></svg>Recordings</button>\n"
"    <button data-nav=\"settings\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6M12 3v3M12 18v3M4 12H1M23 12h-3M5.6 5.6l2 2M16.4 16.4l2 2M18.4 5.6l-2 2M7.6 16.4l-2 2\"/></svg>Settings</button>\n"
"  </nav>\n"
"</header>\n"
"\n"
"<div class=\"appbody\">\n"
"\n"
"<div id=\"batt-warn-banner\" style=\"display:none; align-items:center; gap:12px; flex-wrap:wrap; background:#5a4410; border:1px solid var(--yellow); border-radius:8px; padding:10px 14px; margin-bottom:12px\">\n"
"  <span id=\"batt-warn-text\" style=\"flex:1 1 200px\"></span>\n"
"</div>\n"
"\n"
"<!-- ===================== DASHBOARD ===================== -->\n"
"<div id=\"tab-dashboard\" class=\"apptab\">\n"
"  <div class=\"dash\">\n"
"    <div class=\"card d-ble\" id=\"ble-card\">\n"
"      <h2>Nearby Bluetooth devices <span class=\"sub\" id=\"ble-summary\" style=\"margin-left:auto\">–</span></h2>\n"
"      <div class=\"bletools\">\n"
"        <input type=\"text\" id=\"ble-filter\" placeholder=\"filter: name, address, maker\" oninput=\"bleRender()\">\n"
"        <select id=\"ble-age\" onchange=\"bleAge=+this.value; pollBle()\" title=\"only devices seen within\">\n"
"          <option value=\"10\">seen in last 10 s</option>\n"
"          <option value=\"60\" selected>seen in last 1 min</option>\n"
"          <option value=\"300\">seen in last 5 min</option>\n"
"          <option value=\"0\">all known</option>\n"
"        </select>\n"
"      </div>\n"
"      <div class=\"blewrap\">\n"
"        <table class=\"ble\">\n"
"          <thead><tr>\n"
"            <th data-k=\"n\" onclick=\"bleSortBy('n')\">Name</th>\n"
"            <th data-k=\"a\" onclick=\"bleSortBy('a')\">Address</th>\n"
"            <th data-k=\"r\" class=\"num\" onclick=\"bleSortBy('r')\">RSSI</th>\n"
"            <th data-k=\"ra\" class=\"num\" onclick=\"bleSortBy('ra')\">Avg</th>\n"
"            <th data-k=\"ps\" class=\"num\" onclick=\"bleSortBy('ps')\">Pkt/s</th>\n"
"            <th data-k=\"c\" class=\"num\" onclick=\"bleSortBy('c')\">Total</th>\n"
"            <th data-k=\"l\" class=\"num\" onclick=\"bleSortBy('l')\">Seen</th>\n"
"            <th data-k=\"m\" onclick=\"bleSortBy('m')\">Maker</th>\n"
"            <th data-k=\"p\" onclick=\"bleSortBy('p')\">Kind</th>\n"
"          </tr></thead>\n"
"          <tbody id=\"ble-body\"></tbody>\n"
"        </table>\n"
"        <div class=\"bleempty\" id=\"ble-empty\">Waiting for the scanner…</div>\n"
"      </div>\n"
"    </div>\n"
"\n"
"    <div class=\"card d-ctrl\">\n"
"      <div class=\"recrow\">\n"
"        <button id=\"rec-toggle-btn\" class=\"primary\" onclick=\"toggleRecording()\" style=\"min-width:150px; justify-content:center\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 4a8 8 0 1 0 0 16 8 8 0 0 0 0-16\"/></svg> Start logging</button>\n"
"        <input type=\"text\" id=\"rec-name\" class=\"rec-idle-field\" placeholder=\"session name (optional)\" style=\"flex:1; min-width:130px; margin-top:0\">\n"
"        <div class=\"rec-readout\" id=\"rec-live-readout\" style=\"display:none; flex:1\">\n"
"          <span>Elapsed <b id=\"rec-elapsed\">0:00</b></span>\n"
"          <span>Rows <b id=\"rec-rows\">–</b></span>\n"
"          <span>Size <b id=\"rec-bytes\">–</b></span>\n"
"          <span>Rate <b id=\"rec-rate\">–</b></span>\n"
"          <span>SD left <b id=\"rec-sdleft\">–</b></span>\n"
"        </div>\n"
"        <button id=\"rec-mark-btn\" onclick=\"addMarker(this)\" disabled><svg viewBox=\"0 0 24 24\"><path d=\"M6 3v18l6-4 6 4V3z\"/></svg> Add marker</button>\n"
"      </div>\n"
"      <div class=\"row\" id=\"rec-wifi-row\" style=\"display:none; margin-top:6px\"><span class=\"k\">100 % scan mode</span><span class=\"v\" id=\"rec-wifi\" style=\"color:var(--yellow)\">–</span></div>\n"
"      <div class=\"row\" id=\"rec-error-row\" style=\"display:none; margin-top:6px\"><span class=\"k\">Error</span><span class=\"v\" id=\"rec-error\" style=\"color:var(--red)\">–</span></div>\n"
"      <div class=\"row\" id=\"rec-notice-row\" style=\"display:none; margin-top:6px\"><span class=\"k\">Notice</span><span class=\"v\" id=\"rec-notice\" style=\"color:var(--yellow)\">–</span></div>\n"
"      <div id=\"marker-controls\" style=\"display:none\">\n"
"        <div class=\"mkstrip\" id=\"marker-list\"></div>\n"
"        <div class=\"mkedit\" id=\"marker-edit\" style=\"display:none\">\n"
"          <span class=\"mkedit-lbl\" id=\"mkedit-lbl\">Marker</span>\n"
"          <input type=\"text\" id=\"marker-note\" placeholder=\"note (optional)\" maxlength=\"47\" oninput=\"noteFilter(this)\" onkeydown=\"if(event.key==='Enter')saveMarkerNote()\">\n"
"          <button class=\"primary\" onclick=\"saveMarkerNote()\">Save</button>\n"
"          <button id=\"mkedit-del\" onclick=\"markerEditDelete()\">Delete</button>\n"
"        </div>\n"
"      </div>\n"
"    </div>\n"
"\n"
"    <div class=\"card d-act\">\n"
"      <h2>Air activity <span class=\"sub\" style=\"margin-left:auto\">last 10 min</span></h2>\n"
"      <div class=\"chartbox\"><canvas id=\"act-chart\"></canvas></div>\n"
"      <div class=\"chartlegend\"><span><i style=\"background:var(--accent)\"></i>reports / s</span><span><i style=\"background:var(--green)\"></i>devices heard / s</span></div>\n"
"    </div>\n"
"\n"
"    <div class=\"d-side\">\n"
"      <div class=\"card statuscard\">\n"
"        <h2>Status <span class=\"sub\" style=\"margin-left:auto\">live</span></h2>\n"
"        <div class=\"row\"><span class=\"k\">Bluetooth</span><span class=\"v\"><span id=\"ble-pill\" class=\"pill pending\">–</span></span></div>\n"
"        <div class=\"row\"><span class=\"k\">BLE reports</span><span class=\"v\" id=\"ds-ble-rate\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">BLE dropped</span><span class=\"v\" id=\"ds-ble-drops\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Log rows dropped</span><span class=\"v\" id=\"ds-log-drops\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Battery</span><span class=\"v\" id=\"ds-batt\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Charger</span><span class=\"v\" id=\"ds-chg\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">SD card</span><span class=\"v\" id=\"ds-sd\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Wi-Fi</span><span class=\"v\" id=\"ds-wifi\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Clock</span><span class=\"v\" id=\"ds-clock\">–</span></div>\n"
"      </div>\n"
"      <div class=\"card\">\n"
"        <h2>Motion <span class=\"sub\" style=\"margin-left:auto\">this board</span></h2>\n"
"        <div class=\"row\"><span class=\"k\">State</span><span class=\"v\"><span id=\"mo-pill\" class=\"pill pending\">–</span></span></div>\n"
"        <div class=\"row\"><span class=\"k\">Activity</span><span class=\"v\" id=\"mo-act\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Steps · cadence</span><span class=\"v\" id=\"mo-steps\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Speed · distance</span><span class=\"v\" id=\"mo-speed\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Movement axis</span><span class=\"v\" id=\"mo-axis\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Tilt</span><span class=\"v\" id=\"mo-tilt\">–</span></div>\n"
"      </div>\n"
"      <div class=\"card tglist\">\n"
"        <h2>Target devices <span class=\"sub\" style=\"margin-left:auto\" id=\"tg-count\">–</span></h2>\n"
"        <div id=\"tg-body\"><div class=\"sub\">No target device seen in the last minute.</div></div>\n"
"        <div class=\"sub\" style=\"margin-top:8px\">Rules: <span id=\"tg-rules-short\" style=\"font-family:var(--mono)\">–</span> · <a href=\"#\" onclick=\"goTab('settings'); sSetGroup('bluetooth'); return false\" style=\"color:var(--accent)\">edit</a></div>\n"
"      </div>\n"
"    </div>\n"
"  </div>\n"
"</div>\n"
"\n"
"<!-- ===================== ANALYZE ===================== -->\n"
"<div id=\"tab-analyze\" class=\"apptab\">\n"
"  <div class=\"an2\">\n"
"    <div class=\"card\">\n"
"      <h2>Device</h2>\n"
"      <select id=\"an-dev-select\" onchange=\"anPick(this.value)\" style=\"margin-top:0\">\n"
"        <option value=\"\">— pick a device (or click one on the Dashboard) —</option>\n"
"      </select>\n"
"      <div id=\"an-dev-empty\" class=\"sub\" style=\"margin-top:10px\">Pick a device to see its details, raw payloads and signal history.</div>\n"
"      <div id=\"an-dev\" style=\"display:none; margin-top:10px\">\n"
"        <div class=\"kv\">\n"
"          <span class=\"k\">Name</span><span class=\"v\" id=\"ad-name\">–</span>\n"
"          <span class=\"k\">Address</span><span class=\"v\" id=\"ad-addr\">–</span>\n"
"          <span class=\"k\">Address kind</span><span class=\"v\" id=\"ad-kind\">–</span>\n"
"          <span class=\"k\">Maker</span><span class=\"v\" id=\"ad-maker\">–</span>\n"
"          <span class=\"k\">RSSI now / avg</span><span class=\"v\" id=\"ad-rssi\">–</span>\n"
"          <span class=\"k\">RSSI min / max</span><span class=\"v\" id=\"ad-rssi2\">–</span>\n"
"          <span class=\"k\">Packets</span><span class=\"v\" id=\"ad-count\">–</span>\n"
"          <span class=\"k\">First / last seen</span><span class=\"v\" id=\"ad-seen\">–</span>\n"
"          <span class=\"k\">TX power</span><span class=\"v\" id=\"ad-tx\">–</span>\n"
"          <span class=\"k\">Advertising</span><span class=\"v\" id=\"ad-props\">–</span>\n"
"          <span class=\"k\">Appearance</span><span class=\"v\" id=\"ad-app\">–</span>\n"
"          <span class=\"k\">Service UUID</span><span class=\"v\" id=\"ad-uuid\">–</span>\n"
"          <span class=\"k\">Target</span><span class=\"v\" id=\"ad-target\">–</span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin-top:12px\">Last advertisement (hex, up to 64 bytes)</div>\n"
"        <div class=\"hexbox\" id=\"ad-adv\">–</div>\n"
"        <div class=\"sub\" style=\"margin-top:8px\">Last scan response</div>\n"
"        <div class=\"hexbox\" id=\"ad-rsp\">–</div>\n"
"      </div>\n"
"    </div>\n"
"    <div class=\"an-charts\">\n"
"      <div class=\"card chartcard\">\n"
"        <h2>Signal <span class=\"sub\" style=\"margin-left:auto\">last 2 min, 1 s steps</span></h2>\n"
"        <div class=\"chartbox\"><canvas id=\"an-rssi-chart\"></canvas></div>\n"
"        <div class=\"chartlegend\"><span><i style=\"background:var(--accent)\"></i>mean RSSI (dBm)</span><span><i style=\"background:var(--panel3)\"></i>packets / s</span></div>\n"
"      </div>\n"
"      <div class=\"card chartcard\">\n"
"        <h2>Motion of this board <span class=\"sub\" style=\"margin-left:auto\">last 10 min</span></h2>\n"
"        <div class=\"chartbox\"><canvas id=\"an-mo-chart\"></canvas></div>\n"
"        <div class=\"chartlegend\"><span><i style=\"background:var(--yellow)\"></i>activity (mg)</span><span><i style=\"background:var(--green)\"></i>walking speed (m/s)</span><span id=\"an-mo-sum\"></span></div>\n"
"      </div>\n"
"      <div class=\"card chartcard\">\n"
"        <h2>Air activity <span class=\"sub\" style=\"margin-left:auto\">last 10 min</span></h2>\n"
"        <div class=\"chartbox\"><canvas id=\"an-act-chart\"></canvas></div>\n"
"        <div class=\"chartlegend\"><span><i style=\"background:var(--accent)\"></i>reports / s</span><span><i style=\"background:var(--green)\"></i>devices heard / s</span></div>\n"
"      </div>\n"
"    </div>\n"
"  </div>\n"
"</div>\n"
"\n"
"<!-- ===================== RECORDINGS ===================== -->\n"
"<div id=\"tab-recordings\" class=\"apptab\">\n"
"  <div class=\"card\">\n"
"    <h2>Logging sessions <span class=\"sub\" style=\"margin-left:auto\">CSV files on the SD card (/ble)</span></h2>\n"
"    <div id=\"recordings-body\"></div>\n"
"    <div class=\"btnrow\">\n"
"      <button onclick=\"refreshRecordings()\"><svg viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 1 1-3-6.7M21 4v5h-5\"/></svg> Refresh list</button>\n"
"    </div>\n"
"  </div>\n"
"</div>\n"
"\n"
"<!-- ===================== SETTINGS ===================== -->\n"
"<div id=\"tab-settings\" class=\"apptab\" data-sg=\"bluetooth\">\n"
"  <div class=\"settings2\">\n"
"    <div class=\"snav\">\n"
"      <button class=\"sitem\" data-sg=\"bluetooth\" onclick=\"sSetGroup('bluetooth')\"><svg viewBox=\"0 0 24 24\"><path d=\"M7 7l10 10-5 4V3l5 4L7 17\"/></svg><span>Bluetooth</span></button>\n"
"      <button class=\"sitem active\" data-sg=\"capture\" onclick=\"sSetGroup('capture')\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 7h3l2-3h6l2 3h3v12H4z\"/></svg><span>Motion sensor</span></button>\n"
"      <button class=\"sitem\" data-sg=\"wifi\" onclick=\"sSetGroup('wifi')\"><svg viewBox=\"0 0 24 24\"><path d=\"M5 12a10 10 0 0 1 14 0M8 15a6 6 0 0 1 8 0M12 18h.01\"/></svg><span>Wi-Fi</span></button>\n"
"      <button class=\"sitem\" data-sg=\"power\" onclick=\"sSetGroup('power')\"><svg viewBox=\"0 0 24 24\"><path d=\"M7 8h10v8H7zM17 11v2M9 2v3M15 2v3\"/></svg><span>Power &amp; battery</span></button>\n"
"      <button class=\"sitem\" data-sg=\"device\" onclick=\"sSetGroup('device')\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 16v-5M12 8h.01M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18\"/></svg><span>Device &amp; firmware</span></button>\n"
"    </div>\n"
"    <div class=\"spane\">\n"
"\n"
"      <!-- BLUETOOTH -->\n"
"      <div class=\"card\" data-sgroup=\"bluetooth\">\n"
"        <h2>Scanning</h2>\n"
"        <div class=\"row\">\n"
"          <span class=\"k\"><label for=\"ble-active\">Active scanning</label></span>\n"
"          <span class=\"v\"><input type=\"checkbox\" id=\"ble-active\" onchange=\"setBleConfig('active', this)\"></span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:2px 0 8px\">Sends a scan request to every scannable device, so its scan response arrives too — that is often where the device name is. Off = passive: the scanner never transmits and is invisible to the devices around it, but sees fewer names.</div>\n"
"        <div class=\"row\">\n"
"          <span class=\"k\"><label for=\"ble-coded\">Also scan Coded PHY (long range)</label></span>\n"
"          <span class=\"v\"><input type=\"checkbox\" id=\"ble-coded\" onchange=\"setBleConfig('coded', this)\"></span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:2px 0 0\">Picks up BLE&nbsp;5 long-range advertisers, which few devices use. The radio then splits its time between the 1M and Coded PHYs, so it catches fewer packets from ordinary devices.</div>\n"
"      </div>\n"
"      <div class=\"card\" data-sgroup=\"bluetooth\">\n"
"        <h2>Logging</h2>\n"
"        <div class=\"row\">\n"
"          <span class=\"k\"><label for=\"log-autostart\">Start logging at power-on</label></span>\n"
"          <span class=\"v\"><input type=\"checkbox\" id=\"log-autostart\" onchange=\"setLogConfig('autostart', this)\"></span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:2px 0 8px\">For field use: the board begins a session (named “auto”) as soon as it boots with an SD card in.</div>\n"
"        <div class=\"row\">\n"
"          <span class=\"k\"><label for=\"log-wifioff\">100 % scan mode — Wi-Fi off while logging</label></span>\n"
"          <span class=\"v\"><input type=\"checkbox\" id=\"log-wifioff\" onchange=\"setLogConfig('wifi_off', this)\"></span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:2px 0 8px\"><b style=\"color:var(--yellow)\">Wi-Fi and Bluetooth share one radio.</b> While Wi-Fi is on — even just the access point — the scanner only gets part of the air time and misses some packets. With this on, Wi-Fi switches off 5&nbsp;s after logging starts, so the scanner listens 100&nbsp;% of the time; this dashboard is unreachable until logging stops. Stop with a <b>POWER double-click</b> — Wi-Fi then comes back by itself.</div>\n"
"        <div class=\"row\">\n"
"          <span class=\"k\"><label for=\"button-mark\">Marker on POWER-button click</label></span>\n"
"          <span class=\"v\"><input type=\"checkbox\" id=\"button-mark\" onchange=\"setButtonMark(this)\"></span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:2px 0 8px\">A single click while logging places a marker row in the log; double-click starts/stops logging; a 3&nbsp;s hold powers off.</div>\n"
"        <div class=\"row\">\n"
"          <span class=\"k\"><label for=\"log-serial\">Copy every log row to USB serial</label></span>\n"
"          <span class=\"v\"><input type=\"checkbox\" id=\"log-serial\" onchange=\"setLogConfig('serial', this)\"></span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:2px 0 0\">For live capture on a PC (rows start with <code>BTS,</code>); works with or without an SD session. A slow serial reader can make the scanner drop reports.</div>\n"
"      </div>\n"
"      <div class=\"card\" data-sgroup=\"bluetooth\">\n"
"        <h2>Target devices</h2>\n"
"        <div class=\"sub\" style=\"margin:0\">One rule per line. A device matching any rule is flagged as a target: a <b>TARGET</b> row is logged, the LED flashes magenta, and it's listed on the Dashboard.</div>\n"
"        <div class=\"sub\" style=\"margin:6px 0 0; font-family:var(--mono); line-height:1.7\">name:XXZ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;— name starts with XXZ (case-sensitive)<br>addr:AA:BB:CC:DD:EE:FF — exactly this address<br>prefix:AA:BB:CC &nbsp;&nbsp;&nbsp;&nbsp;— address starts with</div>\n"
"        <textarea id=\"tg-rules\" spellcheck=\"false\" placeholder=\"name:XXZ\"></textarea>\n"
"        <div class=\"btnrow\">\n"
"          <button class=\"primary\" onclick=\"saveTargets(this)\">Save rules</button>\n"
"          <span class=\"sub\" id=\"tg-msg\"></span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:4px 0 0\">Phones and most wearables change their address every few minutes, so address rules only work reliably for devices with a fixed (public / static) address.</div>\n"
"      </div>\n"
"      <div class=\"card\" data-sgroup=\"bluetooth\">\n"
"        <h2>Scanner status</h2>\n"
"        <div class=\"row\"><span class=\"k\">State</span><span class=\"v\" id=\"bs-state\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Reports received</span><span class=\"v\" id=\"bs-total\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Dropped (processing queue full)</span><span class=\"v\" id=\"bs-drops\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Scan restarts</span><span class=\"v\" id=\"bs-restarts\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Devices in table</span><span class=\"v\" id=\"bs-devices\">–</span></div>\n"
"        <div class=\"sub\" style=\"margin:6px 0 0\">Scanning is continuous with no duplicate filter: every advertisement and scan response is received, legacy and BLE&nbsp;5 extended. Wi-Fi shares the same radio, so while Wi-Fi is on the scanner gets less than 100&nbsp;% of the air time. Reports the radio controller itself discards under heavy load are not counted here.</div>\n"
"      </div>\n"
"\n"
"      <!-- CAPTURE -->\n"
"      <div class=\"card\" data-sgroup=\"capture\">\n"
"        <h2>Motion sensor</h2>\n"
"        <div class=\"config-row\" style=\"margin-top:0\">\n"
"          <label>Measurement range\n"
"            <select id=\"mo-range\" onchange=\"setMotionConfig('range', +this.value)\">\n"
"              <option value=\"2\">±2 g</option>\n"
"              <option value=\"4\">±4 g</option>\n"
"              <option value=\"8\">±8 g</option>\n"
"              <option value=\"16\">±16 g</option>\n"
"            </select>\n"
"          </label>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:4px 0 8px\">±4&nbsp;g (default) covers walking, running and handling; use ±8/16&nbsp;g only if hard knocks clip. The IIS3DWB samples at 26.7&nbsp;kHz; the board averages that down to ~100&nbsp;Hz. Its filter stays off — a high-pass would remove gravity, which tilt and step detection need.</div>\n"
"        <div class=\"row\">\n"
"          <span class=\"k\"><label for=\"mo-log\">Log 100 Hz acceleration (<code>.motion.csv</code>)</label></span>\n"
"          <span class=\"v\"><input type=\"checkbox\" id=\"mo-log\" onchange=\"setMotionConfig('log', this.checked ? 1 : 0)\"></span>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin:2px 0 8px\">Each logging session then also gets <code>&lt;name&gt;.motion.csv</code> (time, x, y, z in g, ~3&nbsp;KB/s) on the same clock as the scan log, for your own analysis. The once-per-second MOTION rows in the scan log are written either way.</div>\n"
"        <div class=\"row\"><span class=\"k\">Sample rate</span><span class=\"v\" id=\"mo-rate\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Samples lost</span><span class=\"v\" id=\"mo-drop\">–</span></div>\n"
"        <div class=\"sub\" style=\"margin:6px 0 0\">What the board can tell from acceleration alone (no gyroscope, no compass): still / moving / walking, steps and cadence, an estimated walking speed and distance, the main horizontal axis it moves along (relative to the board, 180° ambiguous, needs a few seconds to settle after the board is turned) and its tilt. No absolute heading and no position tracking.</div>\n"
"      </div>\n"
"\n"
"      <div class=\"card\" data-sgroup=\"capture\">\n"
"        <h2>Sensor self-test</h2>\n"
"        <div class=\"sub\" style=\"margin:0 0 8px\">IIS3DWB electrostatic self-test — checks each axis against the datasheet's 800-3200&nbsp;mg range. Keep the device still; not during a recording.</div>\n"
"        <div class=\"row\"><span class=\"k\">Last result</span><span class=\"v\" id=\"selftest-result\">–</span></div>\n"
"        <div class=\"btnrow\">\n"
"          <button onclick=\"accelSelfTest(this)\" id=\"selftest-btn\">Run self-test</button>\n"
"        </div>\n"
"      </div>\n"
"\n"
"      <!-- WIFI -->\n"
"      <div class=\"card\" data-sgroup=\"wifi\">\n"
"        <h2>Connection</h2>\n"
"        <div class=\"row\"><span class=\"k\">Device name</span><span class=\"v\" id=\"wifi-host\" title=\"This device's unique name — always reachable at <name>.local, so multiple boards never collide.\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Access point</span><span class=\"v\" id=\"wifi-ap\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Infra status</span><span class=\"v\" id=\"wifi-state\">–</span></div>\n"
"        <div class=\"row\" id=\"wifi-fail-row\" style=\"display:none\"><span class=\"k\">Reason</span><span class=\"v\" id=\"wifi-fail-reason\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">IP address</span><span class=\"v\" id=\"wifi-ip\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">NTP synced</span><span class=\"v\" id=\"wifi-ntp\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Clock</span><span class=\"v\" id=\"wifi-time\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Sync clock (TSF)</span><span class=\"v\" id=\"wifi-tsf\" title=\"802.11 TSF timer — a microsecond clock all devices on this AP share (disciplined to the AP's beacon). The basis for time-aligning recordings across multiple devices.\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Answer to btscanner.local</span><span class=\"v\"><input type=\"checkbox\" id=\"mdns-friendly\" onchange=\"setMdnsFriendly(this)\"></span></div>\n"
"        <div class=\"row\"><span class=\"k\" title=\"Periodically tells the update server this device's current local IP (and basic status: hostname, Wi-Fi, battery, recording) so you can find it via the server's find page. Uses the same server as firmware updates; does nothing until one is configured.\">Send status reports</span><span class=\"v\"><input type=\"checkbox\" id=\"report-enabled\" onchange=\"setReportEnabled(this)\"></span></div>\n"
"        <div class=\"row\" id=\"wifi-txpower-row\" style=\"display:none\"><span class=\"k\">TX power</span><span class=\"v\" style=\"color:var(--yellow)\">reduced (repeated brownouts)</span></div>\n"
"      </div>\n"
"      <div class=\"sub\" data-sgroup=\"wifi\" style=\"margin:-4px 2px 0\">Each device always has its own <b>&lt;device name&gt;.local</b>. With several devices, keep this on for only one (your main board) so <b>btscanner.local</b> isn't ambiguous.</div>\n"
"\n"
"      <div class=\"card\" data-sgroup=\"wifi\">\n"
"        <h2>Access point</h2>\n"
"        <div class=\"row\"><span class=\"k\">Current AP</span><span class=\"v\" id=\"wifi-cur-bssid\" style=\"font-family:var(--mono); font-size:12px\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">AP selection</span><span class=\"v\" id=\"wifi-pin-state\">Automatic (strongest)</span></div>\n"
"        <div class=\"sub\" style=\"margin:2px 0 8px\">Normally the device joins the strongest AP of its network. Pin it to one specific AP so several BTScanner devices share the same access point — needed for time-aligned (TSF) recordings. If that AP is out of range it falls back to a normal connect, so this never strands the device.</div>\n"
"        <div class=\"btnrow\">\n"
"          <button type=\"button\" id=\"ap-choose-btn\" onclick=\"apScan()\">Pin to a specific AP…</button>\n"
"          <button type=\"button\" id=\"ap-unpin-btn\" onclick=\"apClearPin()\" style=\"display:none\">Back to automatic</button>\n"
"        </div>\n"
"        <div id=\"ap-list\" style=\"display:none; margin-top:10px\"></div>\n"
"      </div>\n"
"\n"
"      <div class=\"card\" data-sgroup=\"wifi\">\n"
"        <h2>Saved networks</h2>\n"
"        <div id=\"wifi-saved-body\"><div class=\"sub\">None saved yet.</div></div>\n"
"      </div>\n"
"\n"
"      <div class=\"card\" data-sgroup=\"wifi\">\n"
"        <h2>Add a network</h2>\n"
"        <div class=\"btnrow\" style=\"margin-top:0\">\n"
"          <button onclick=\"wifiScan(this)\" id=\"wifi-scan-btn\"><svg viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 1 1-3-6.7M21 4v5h-5\"/></svg> Scan for networks</button>\n"
"        </div>\n"
"        <select id=\"wifi-networks\" class=\"wifi-net-list\" onchange=\"wifiPickNetwork()\">\n"
"          <option value=\"\">— select a scanned network —</option>\n"
"        </select>\n"
"        <input type=\"text\" id=\"wifi-ssid\" placeholder=\"SSID\">\n"
"        <label style=\"display:flex; align-items:center; gap:6px; font-size:12px; color:var(--muted); margin:8px 0 2px\">\n"
"          <input type=\"checkbox\" id=\"wifi-enterprise\" onchange=\"wifiUpdateEnterprise()\"> Enterprise login (WPA2/WPA3-Enterprise)\n"
"        </label>\n"
"        <input type=\"text\" id=\"wifi-user\" placeholder=\"Username / identity (e.g. w59v46)\" style=\"display:none\">\n"
"        <div class=\"pwrow\">\n"
"          <input type=\"password\" id=\"wifi-pass\" placeholder=\"Password\">\n"
"          <button type=\"button\" onclick=\"wifiTogglePass(this)\">Show</button>\n"
"        </div>\n"
"        <div class=\"sub\" id=\"wifi-enterprise-note\" style=\"display:none; margin-top:6px\">\n"
"          Uses your username + password (e.g. a university login), no shared key. The server certificate is not verified —\n"
"          same as a phone with no CA certificate set. Credentials are stored on the device.\n"
"        </div>\n"
"        <div class=\"btnrow\">\n"
"          <button class=\"primary\" onclick=\"wifiConnect(this)\">Connect &amp; save</button>\n"
"        </div>\n"
"      </div>\n"
"\n"
"      <!-- POWER -->\n"
"      <div class=\"card\" data-sgroup=\"power\">\n"
"        <h2>Power &amp; charger (BQ25628)</h2>\n"
"        <div class=\"row\"><span class=\"k\">Power source</span><span class=\"v\" id=\"chg-source\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">VBUS</span><span class=\"v\" id=\"chg-vbus\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">VBAT</span><span class=\"v\" id=\"chg-vbat\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">VSYS</span><span class=\"v\" id=\"chg-vsys\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Charge current (battery)</span><span class=\"v\" id=\"chg-ichg\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Input current (USB)</span><span class=\"v\" id=\"chg-ibus\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Charger die temp</span><span class=\"v\" id=\"chg-tdie\">–</span></div>\n"
"        <div class=\"row\" id=\"chg-flags-row\" style=\"display:none\"><span class=\"k\">Charge status</span><span class=\"v\" id=\"chg-flags\" style=\"color:var(--yellow)\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">TS status</span><span class=\"v\" id=\"chg-ts\">–</span></div>\n"
"        <div class=\"row\">\n"
"          <span class=\"k\"><label for=\"chg-ts-ignore\">Ignore TS (no NTC)</label></span>\n"
"          <span class=\"v\"><input type=\"checkbox\" id=\"chg-ts-ignore\" onchange=\"chgSetTsIgnore(this)\"></span>\n"
"        </div>\n"
"        <div class=\"btnrow\">\n"
"          <button class=\"danger\" onclick=\"shipMode(this)\"><svg viewBox=\"0 0 24 24\"><path d=\"M7 8h10v8H7zM9 2v3M15 2v3M17 11v2\"/></svg> Enter ship mode</button>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin-top:6px\">Same as a 3&nbsp;s long-press on POWER — safely stops any recording first. Charge current, voltage and the low-battery cutoffs are fixed in firmware to protect the cell.</div>\n"
"      </div>\n"
"\n"
"      <div class=\"card\" data-sgroup=\"power\">\n"
"        <h2>POWER button</h2>\n"
"        <div class=\"sub\" style=\"line-height:1.9; color:var(--muted)\">\n"
"          <div>Double-click → <b style=\"color:var(--text)\">start / stop recording</b></div>\n"
"          <div>Single click while recording → <b style=\"color:var(--text)\">add marker</b> (if enabled)</div>\n"
"          <div>Hold 3&nbsp;s → <b style=\"color:var(--text)\">ship mode</b></div>\n"
"        </div>\n"
"      </div>\n"
"\n"
"      <!-- DEVICE -->\n"
"      <div class=\"card\" data-sgroup=\"device\">\n"
"        <h2>Firmware</h2>\n"
"        <div class=\"row\"><span class=\"k\">Running from</span><span class=\"v\" id=\"ota-partition\">–</span></div>\n"
"        <div class=\"row\" id=\"ota-unavail-row\" style=\"display:none\"><span class=\"v\" style=\"color:var(--yellow)\">Not available yet — flash the OTA partition layout over USB once.</span></div>\n"
"        <div class=\"config-row\">\n"
"          <button type=\"button\" id=\"ota-check\" onclick=\"checkForUpdate()\"><svg viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 1 1-3-6.7M21 4v5h-5\"/></svg> Check for updates</button>\n"
"          <button type=\"button\" class=\"primary\" id=\"ota-install\" onclick=\"installCloudUpdate()\" style=\"display:none\">Install <span id=\"ota-latest\"></span></button>\n"
"        </div>\n"
"        <div class=\"sub\" id=\"ota-check-result\" style=\"margin-top:8px; display:none\"></div>\n"
"        <div id=\"ota-drop\" class=\"config-row\">\n"
"          <input type=\"file\" id=\"ota-file\" accept=\".bin\" onchange=\"uploadFirmware(this)\" hidden>\n"
"          <button type=\"button\" id=\"ota-pick\" onclick=\"document.getElementById('ota-file').click()\">Choose firmware.bin…</button>\n"
"          <span class=\"sub\">or drop a file here</span>\n"
"        </div>\n"
"        <progress id=\"ota-progress\" value=\"0\" max=\"100\" style=\"display:none\"></progress>\n"
"        <div class=\"sub\" id=\"ota-status\" style=\"margin-top:8px\">Check the server for the latest release, or drop / pick a <code>firmware.bin</code> built from this project. The device verifies the image, switches to it, and reboots (with automatic rollback if it fails to boot). <b>Don't update during a recording.</b></div>\n"
"      </div>\n"
"\n"
"      <div class=\"card\" id=\"ota-server-card\" data-sgroup=\"device\" style=\"display:none\">\n"
"        <h2>Update server</h2>\n"
"        <div class=\"sub\">Where <b>Check for updates</b> looks for new firmware (a Cloudflare Worker fronting the GitHub releases). Stored on the device.</div>\n"
"        <div class=\"sub\" style=\"margin-top:8px\">Server URL</div>\n"
"        <input type=\"text\" id=\"ota-url\" placeholder=\"https://your-worker.workers.dev\" autocomplete=\"off\" onblur=\"cleanOtaField(this,true)\">\n"
"        <div class=\"sub\" style=\"margin-top:8px\">CF-Access Client Id</div>\n"
"        <input type=\"text\" id=\"ota-cfid\" placeholder=\"xxxxxxxx.access\" autocomplete=\"off\" onblur=\"cleanOtaField(this,false)\">\n"
"        <div class=\"sub\" style=\"margin-top:8px\">CF-Access Client Secret</div>\n"
"        <input type=\"password\" id=\"ota-cfsecret\" placeholder=\"leave blank to keep the current secret\" autocomplete=\"new-password\" onblur=\"cleanOtaField(this,false)\">\n"
"        <div class=\"btnrow\"><button type=\"button\" class=\"primary\" onclick=\"saveUpdateServer()\">Save</button> <span class=\"sub\" id=\"ota-server-status\"></span></div>\n"
"      </div>\n"
"\n"
"      <div class=\"card\" data-sgroup=\"device\">\n"
"        <h2>SD card</h2>\n"
"        <div class=\"row\"><span class=\"k\">Mounted</span><span class=\"v\" id=\"sd-mounted\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Free space</span><span class=\"v\" id=\"sd-free\">–</span></div>\n"
"        <progress id=\"sd-usage\" value=\"0\" max=\"100\" style=\"display:none\"></progress>\n"
"        <div class=\"row\" style=\"margin-top:8px\"><span class=\"k\">Benchmark</span><span class=\"v\"><span id=\"bench-pill\" class=\"pill pending\">IDLE</span></span></div>\n"
"        <div class=\"row\"><span class=\"k\">Write speed</span><span class=\"v\" id=\"bench-write\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Read speed</span><span class=\"v\" id=\"bench-read\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Worst chunk</span><span class=\"v\" id=\"bench-worst\">–</span></div>\n"
"        <div class=\"row\" id=\"bench-error-row\" style=\"display:none\"><span class=\"k\">Error</span><span class=\"v\" id=\"bench-error\" style=\"color:var(--red)\">–</span></div>\n"
"        <progress id=\"bench-progress\" value=\"0\" max=\"100\" style=\"display:none\"></progress>\n"
"        <div class=\"btnrow\">\n"
"          <button onclick=\"runBenchmark(this)\">Run benchmark (~64 MB)</button>\n"
"          <button onclick=\"remountSd(this)\">Remount SD</button>\n"
"        </div>\n"
"        <div class=\"sub\" style=\"margin-top:6px\">Hot-swap is polled automatically and shown live in the top status bar; Remount is a manual backup. The benchmark is independent of recording — just to see what a card can do.</div>\n"
"      </div>\n"
"\n"
"      <div class=\"card\" data-sgroup=\"device\">\n"
"        <h2>Identity &amp; chip</h2>\n"
"        <div class=\"row\"><span class=\"k\">Device</span><span class=\"v\" id=\"about-name\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Device ID</span><span class=\"v\" id=\"about-id\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Firmware</span><span class=\"v\" id=\"about-fw\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Built</span><span class=\"v\" id=\"about-build\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Last restart</span><span class=\"v\" id=\"about-reset\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">CPU</span><span class=\"v\" id=\"chip-cpu\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Flash / PSRAM</span><span class=\"v\" id=\"chip-mem\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Free heap</span><span class=\"v\" id=\"chip-heap\">–</span></div>\n"
"        <div class=\"row\"><span class=\"k\">Sensor ODR</span><span class=\"v\" id=\"about-odr\" title=\"Measured accelerometer output data rate — the true sampling rate, from the sensor's own clock\">–</span></div>\n"
"        <div class=\"sub\" id=\"about-credit\" style=\"margin-top:10px\">–</div>\n"
"      </div>\n"
"\n"
"      <div class=\"card\" data-sgroup=\"device\">\n"
"        <h2>Fun</h2>\n"
"        <div class=\"sub\" style=\"margin:0 0 10px\">Blink the status LED in a colourful pattern for a few seconds — a rainbow on the RGB boards, a strobe on the plain ones.</div>\n"
"        <div class=\"btnrow\" style=\"margin-top:0\">\n"
"          <button class=\"primary\" onclick=\"partyMode(this)\">🎉 Party mode</button>\n"
"        </div>\n"
"        <!-- TEMPORARY: RGB LED colour tester, for picking status colours. Remove later. -->\n"
"        <div class=\"sub\" style=\"margin:14px 0 6px\">LED colour tester <span style=\"color:var(--faint)\">(temporary — RGB boards only)</span></div>\n"
"        <div class=\"rowf\" style=\"align-items:center; gap:10px\">\n"
"          <input type=\"color\" id=\"led-test-color\" value=\"#ff8000\" oninput=\"ledTest(this.value)\" style=\"width:52px; height:34px; padding:2px; background:var(--bg2); border:1px solid var(--border); border-radius:7px; cursor:pointer\">\n"
"          <span class=\"mono\" id=\"led-test-val\" style=\"font-size:12px; color:var(--muted)\">#ff8000 · rgb(255,128,0)</span>\n"
"          <button id=\"led-test-off\" onclick=\"ledTestOff(this)\">Off</button>\n"
"          <span class=\"sub\" id=\"led-test-note\" style=\"display:none; color:var(--faint)\">disabled while recording</span>\n"
"        </div>\n"
"      </div>\n"
"\n"
"    </div>\n"
"  </div>\n"
"</div>\n"
"\n"
"</div><!-- /appbody -->\n"
"\n"
"<nav class=\"bottomnav\">\n"
"  <button data-nav=\"dashboard\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 13h4l2-8 4 14 3-9 2 3h4\"/></svg>Dashboard</button>\n"
"  <button data-nav=\"analyze\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 12h3l2-7 3 12 3-9 2 4h5M3 20h18\"/></svg>Analyze</button>\n"
"  <button data-nav=\"recordings\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16M4 12h16M4 18h10\"/></svg>Files</button>\n"
"  <button data-nav=\"settings\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6M12 3v3M12 18v3M4 12H1M23 12h-3M5.6 5.6l2 2M16.4 16.4l2 2M18.4 5.6l-2 2M7.6 16.4l-2 2\"/></svg>Settings</button>\n"
"</nav>\n"
"\n"
"<div class=\"menu\" id=\"rec-menu\"></div>\n"
"<div class=\"backdrop\" id=\"rec-backdrop\"><div class=\"sheet\" id=\"rec-sheet\"></div></div>\n"
"<div class=\"toast\" id=\"rec-toast\"></div>\n"
"\n"
"<script>\n"
"/* ===================== dashboard logic ===================== */\n"
"\n"
"// --- Status polling (slow-changing state: recording, charger, wifi, sd) --\n"
"\n"
"function setText(id, text) {\n"
"  var el = document.getElementById(id);\n"
"  if (el) el.textContent = text;\n"
"}\n"
"\n"
"function pillHtml(id, text, cls) {\n"
"  var el = document.getElementById(id);\n"
"  if (el) { el.textContent = text; el.className = 'pill ' + cls; }\n"
"}\n"
"\n"
"// Status-bar Wi-Fi signal bars. rssi (dBm) -> 1..4 lit bars; null = not\n"
"// connected (all dimmed).\n"
"function setWifiBars(rssi) {\n"
"  var box = document.getElementById('sb-wifi-bars');\n"
"  if (!box) return;\n"
"  var level = 0;\n"
"  if (rssi != null) level = rssi > -60 ? 4 : rssi > -70 ? 3 : rssi > -80 ? 2 : 1;\n"
"  var bars = box.children;\n"
"  for (var i = 0; i < bars.length; i++) bars[i].className = i < level ? '' : 'off';\n"
"  box.title = rssi != null ? ('Wi-Fi ' + rssi + ' dBm') : 'Wi-Fi not connected';\n"
"}\n"
"\n"
"function fmtBytes(n) {\n"
"  if (n < 1024) return n + ' B';\n"
"  if (n < 1024*1024) return (n/1024).toFixed(1) + ' KB';\n"
"  if (n < 1024*1024*1024) return (n/1024/1024).toFixed(2) + ' MB';\n"
"  return (n/1024/1024/1024).toFixed(2) + ' GB';\n"
"}\n"
"\n"
"var recordingActive = false;\n"
"var streamModeSynced = false;\n"
"var tsIgnoreSynced = false;\n"
"var browserTimeSynced = false;\n"
"var decimRateLabelSet = false;\n"
"var savedNetworks = [];\n"
"\n"
"function update(data) {\n"
"  if (data.chip) {\n"
"    setText('chip-cpu', data.chip.cores + ' cores @ ' + data.chip.freq_mhz + ' MHz');\n"
"    setText('chip-mem', data.chip.flash_mb + ' MB flash / ' + data.chip.psram_mb + ' MB PSRAM');\n"
"    if (data.chip.free_heap != null) setText('chip-heap', fmtBytesShort(data.chip.free_heap) + ' free');\n"
"  }\n"
"\n"
"  if (data.device) {\n"
"    var dev = data.device;\n"
"    setText('about-name', dev.name);\n"
"    setText('about-id', dev.id);\n"
"    setText('about-fw', 'v' + dev.fw);\n"
"    setText('about-build', dev.build);\n"
"    var reset = dev.reset_reason || '-';\n"
"    setText('about-reset', reset);\n"
"    document.getElementById('about-reset').style.color =\n"
"      (reset.indexOf('brownout') >= 0 || reset.indexOf('panic') >= 0 ||\n"
"       reset.indexOf('watchdog') >= 0) ? 'var(--yellow)' : '';\n"
"    setText('about-credit', 'Made by ' + dev.author);\n"
"  }\n"
"\n"
"  if (data.accel) {\n"
"    var odr = data.accel.measured_odr_hz;\n"
"    setText('about-odr', (odr && odr > 0) ? (odr / 1000).toFixed(3) + ' kHz (measured)' : 'measuring…');\n"
"  }\n"
"  if (data.motion) updateMotion(data.motion);\n"
"\n"
"  if (data.recording) {\n"
"    var R = data.recording;\n"
"    recordingActive = R.active;\n"
"    var recBtn = document.getElementById('rec-toggle-btn');\n"
"    if (recBtn) {\n"
"      recBtn.className = recordingActive ? 'danger' : 'primary';\n"
"      recBtn.innerHTML = recordingActive\n"
"        ? '<svg viewBox=\"0 0 24 24\"><path d=\"M6 6h12v12H6z\"/></svg> Stop logging'\n"
"        : '<svg viewBox=\"0 0 24 24\"><path d=\"M12 4a8 8 0 1 0 0 16 8 8 0 0 0 0-16\"/></svg> Start logging';\n"
"    }\n"
"    var markBtn = document.getElementById('rec-mark-btn');\n"
"    if (markBtn) markBtn.disabled = !recordingActive;\n"
"    // The LED colour tester only works while idle (the LED shows logging state).\n"
"    var ltc = document.getElementById('led-test-color');\n"
"    var lto = document.getElementById('led-test-off');\n"
"    var ltn = document.getElementById('led-test-note');\n"
"    if (ltc) ltc.disabled = recordingActive;\n"
"    if (lto) lto.disabled = recordingActive;\n"
"    if (ltn) ltn.style.display = recordingActive ? '' : 'none';\n"
"    var idleFields = document.querySelectorAll('.rec-idle-field');\n"
"    for (var ri = 0; ri < idleFields.length; ri++) idleFields[ri].style.display = recordingActive ? 'none' : '';\n"
"    document.getElementById('rec-live-readout').style.display = recordingActive ? '' : 'none';\n"
"    if (recordingActive) {\n"
"      setText('rec-elapsed', fmtDur(R.elapsed_s || 0));\n"
"      setText('rec-rows', fmtCount(R.rows || 0));\n"
"      setText('rec-bytes', fmtBytes(R.bytes_written || 0));\n"
"      setText('rec-rate', R.rate_bps > 0 ? fmtBytesShort(R.rate_bps) + '/s' : '–');\n"
"      setText('rec-sdleft', (recSdFree > 0 && R.rate_bps > 0) ? ('~' + fmtDur(recSdFree / R.rate_bps)) : '–');\n"
"    }\n"
"    setText('ds-log-drops', String(R.log_drops || 0));\n"
"    var wr = document.getElementById('rec-wifi-row');\n"
"    if (R.wifi_off_in >= 0) {\n"
"      setText('rec-wifi', 'Wi-Fi turns off in ' + R.wifi_off_in + ' s — this page then stops updating. Stop logging with a POWER double-click to get Wi-Fi back.');\n"
"      wr.style.display = '';\n"
"    } else {\n"
"      wr.style.display = 'none';\n"
"    }\n"
"    var recErrRow = document.getElementById('rec-error-row');\n"
"    if (R.last_error) { setText('rec-error', R.last_error); recErrRow.style.display = ''; }\n"
"    else recErrRow.style.display = 'none';\n"
"    var recNoticeRow = document.getElementById('rec-notice-row');\n"
"    if (R.notice) { setText('rec-notice', R.notice); recNoticeRow.style.display = ''; }\n"
"    else recNoticeRow.style.display = 'none';\n"
"    document.getElementById('marker-controls').style.display = recordingActive ? '' : 'none';\n"
"    if (recordingActive) {\n"
"      if (R.markers !== lastMarkerCount) {\n"
"        lastMarkerCount = R.markers;\n"
"        refreshMarkerList();\n"
"      }\n"
"    } else if (lastMarkerCount !== -1) {\n"
"      lastMarkerCount = -1;\n"
"      closeMarkerEdit();\n"
"    }\n"
"  }\n"
"\n"
"  if (data.ble) updateBleStatus(data.ble);\n"
"\n"
"  if (data.settings) {\n"
"    var bm = document.getElementById('button-mark');\n"
"    if (bm && document.activeElement !== bm) bm.checked = !!data.settings.button_mark;\n"
"    [['log-autostart', 'autostart'], ['log-wifioff', 'wifi_off'], ['log-serial', 'serial']].forEach(function (p) {\n"
"      var el = document.getElementById(p[0]);\n"
"      if (el && document.activeElement !== el) el.checked = !!data.settings[p[1]];\n"
"    });\n"
"  }\n"
"\n"
"  if (data.ota) {\n"
"    setText('ota-partition', data.ota.partition || '-');\n"
"    document.getElementById('ota-unavail-row').style.display = data.ota.available ? 'none' : '';\n"
"    var otaAvail = data.ota.available;\n"
"    document.getElementById('ota-file').disabled = !otaAvail;\n"
"    document.getElementById('ota-pick').disabled = !otaAvail;\n"
"    document.getElementById('ota-check').disabled = !otaAvail || data.ota.cloud_active;\n"
"    updateCloudInstall(data.ota);\n"
"  }\n"
"\n"
"  if (data.selftest) {\n"
"    var st = data.selftest;\n"
"    var stBtn = document.getElementById('selftest-btn');\n"
"    var stRes = document.getElementById('selftest-result');\n"
"    if (st.state === 'running') {\n"
"      if (stBtn) stBtn.disabled = true;\n"
"      setText('selftest-result', 'running...');\n"
"      stRes.style.color = 'var(--muted)';\n"
"    } else {\n"
"      // Re-enabled once it settles, unless a recording is in progress (the\n"
"      // test perturbs capture, so it's blocked during recording).\n"
"      if (stBtn) stBtn.disabled = recordingActive;\n"
"      if (st.state === 'pass') {\n"
"        setText('selftest-result', 'PASS (' + st.x_mg + '/' + st.y_mg + '/' + st.z_mg + ' mg)');\n"
"        stRes.style.color = 'var(--green)';\n"
"      } else if (st.state === 'fail') {\n"
"        setText('selftest-result', 'FAIL (' + st.x_mg + '/' + st.y_mg + '/' + st.z_mg +\n"
"          ' mg; each axis needs ' + st.min_mg + '-' + st.max_mg + ')');\n"
"        stRes.style.color = 'var(--red)';\n"
"      } else {\n"
"        setText('selftest-result', '-');\n"
"        stRes.style.color = '';\n"
"      }\n"
"    }\n"
"  }\n"
"\n"
"  if (data.sdcard) {\n"
"    var sd = data.sdcard;\n"
"    document.getElementById('sd-dot').className = 'dot ' + (sd.mounted ? 'live' : 'bad');\n"
"    document.getElementById('sd-remount-btn').style.display = sd.mounted ? 'none' : '';\n"
"    var haveSpace = sd.mounted && sd.total_bytes > 0;\n"
"    recSdFree = haveSpace ? sd.free_bytes : 0; // feeds the record readout's \"SD left\" estimate\n"
"    var freeStr = haveSpace ? fmtBytesShort(sd.free_bytes) : '';\n"
"    setText('sd-status-text', sd.mounted ? ('SD' + (haveSpace ? ' · ' + freeStr + ' free' : ' mounted')) : 'SD not mounted');\n"
"    setText('sd-mounted', sd.mounted ? 'yes' : 'no');\n"
"    setText('sd-free', haveSpace ? (freeStr + ' of ' + fmtBytesShort(sd.total_bytes)) : (sd.mounted ? '-' : 'no card'));\n"
"    var usage = document.getElementById('sd-usage');\n"
"    if (haveSpace) {\n"
"      usage.style.display = '';\n"
"      usage.value = Math.round((sd.total_bytes - sd.free_bytes) / sd.total_bytes * 100);\n"
"    } else {\n"
"      usage.style.display = 'none';\n"
"    }\n"
"  }\n"
"\n"
"  if (data.sdbench) {\n"
"    var b = data.sdbench;\n"
"    var cls = 'pending';\n"
"    if (b.state === 'done') cls = b.checksum_ok ? 'ok' : 'bad';\n"
"    if (b.state === 'failed') cls = 'bad';\n"
"    if (b.state === 'writing' || b.state === 'reading') cls = 'warn';\n"
"    pillHtml('bench-pill', b.state.toUpperCase(), cls);\n"
"    setText('bench-write', b.write_mb_s > 0 ? b.write_mb_s.toFixed(2) + ' MB/s' : '-');\n"
"    setText('bench-read', b.read_mb_s > 0 ? b.read_mb_s.toFixed(2) + ' MB/s' : '-');\n"
"    setText('bench-worst', b.worst_chunk_ms > 0 ? b.worst_chunk_ms + ' ms' : '-');\n"
"    document.getElementById('bench-error-row').style.display = b.error ? '' : 'none';\n"
"    setText('bench-error', b.error || '-');\n"
"    var prog = document.getElementById('bench-progress');\n"
"    if (b.state === 'writing' || b.state === 'reading') {\n"
"      prog.style.display = '';\n"
"      prog.value = b.total_bytes > 0 ? (b.bytes_done / b.total_bytes * 100) : 0;\n"
"    } else {\n"
"      prog.style.display = 'none';\n"
"    }\n"
"  }\n"
"\n"
"  if (data.charger) {\n"
"    var chgDot = document.getElementById('chg-dot');\n"
"    if (data.charger.ok) {\n"
"      var battPresent = !(data.battery && data.battery.present === false);\n"
"      var vbat = (data.charger.vbat_mv / 1000).toFixed(2);\n"
"      var sourceLabel = !battPresent ? 'USB — no battery'\n"
"        : (data.charger.on_battery ? 'Battery' : ('USB (' + data.charger.chg_phase + ')'));\n"
"      setText('chg-source', sourceLabel);\n"
"      setText('chg-vbus', (data.charger.vbus_mv / 1000).toFixed(2) + ' V');\n"
"      setText('chg-vbat', vbat + ' V'); // raw reading -- a technical detail, always shown\n"
"      setText('chg-vsys', (data.charger.vsys_mv / 1000).toFixed(2) + ' V');\n"
"      setText('chg-ichg', data.charger.ichg_ma + ' mA');\n"
"      setText('chg-ibus', data.charger.ibus_ma + ' mA');\n"
"      setText('chg-tdie', data.charger.tdie_c.toFixed(1) + ' °C');\n"
"      var chgFlags = [];\n"
"      if (data.charger.thermal_regulation) chgFlags.push('thermal throttling');\n"
"      if (data.charger.input_current_limited) chgFlags.push('input-current limited');\n"
"      if (data.charger.input_voltage_limited) chgFlags.push('input-voltage limited (source sag)');\n"
"      var chgFlagsRow = document.getElementById('chg-flags-row');\n"
"      if (chgFlags.length) { setText('chg-flags', chgFlags.join(', ')); chgFlagsRow.style.display = ''; }\n"
"      else { chgFlagsRow.style.display = 'none'; }\n"
"      setText('chg-ts', data.charger.ts_status + (data.charger.fault ? ' (FAULT)' : ''));\n"
"      if (!tsIgnoreSynced) {\n"
"        tsIgnoreSynced = true;\n"
"        document.getElementById('chg-ts-ignore').checked = data.charger.ts_ignore;\n"
"      }\n"
"      // Deliberately two separate, unambiguous status-bar items rather than\n"
"      // one combined string -- \"USB 3.76V\" reads as \"USB supplies 3.76V\"\n"
"      // when it's actually the battery voltage, regardless of source.\n"
"      var stateText = data.charger.fault ? 'Fault'\n"
"        : !battPresent ? 'USB (no battery)'\n"
"        : data.charger.on_battery ? 'On battery'\n"
"        : data.charger.charging ? 'Charging'\n"
"        : 'USB (idle)';\n"
"      chgDot.className = 'dot ' + (data.charger.fault ? 'bad' : (data.charger.on_battery ? 'warn' : 'live'));\n"
"      setText('chg-status-text', stateText);\n"
"      setText('chg-batt-text', 'Bat ' + vbat + 'V');\n"
"    } else {\n"
"      setText('chg-source', 'n/a'); setText('chg-vbus', 'n/a'); setText('chg-vbat', 'n/a');\n"
"      setText('chg-vsys', 'n/a'); setText('chg-ichg', 'n/a'); setText('chg-ts', 'not available');\n"
"      setText('chg-ibus', 'n/a'); setText('chg-tdie', 'n/a');\n"
"      document.getElementById('chg-flags-row').style.display = 'none';\n"
"      chgDot.className = 'dot';\n"
"      setText('chg-status-text', 'Charger n/a');\n"
"      setText('chg-batt-text', '');\n"
"    }\n"
"  }\n"
"\n"
"  if (data.battery && data.charger) {\n"
"    // Best-effort, self-improving estimate -- see power_ctrl.c. Only shown\n"
"    // when the charger reads actually succeeded: the percent is only\n"
"    // refreshed inside refresh_status()'s ok branch, so on a charger-read\n"
"    // failure it's stale/zero -- showing \"0%\" right next to the Power\n"
"    // card's own \"n/a\" would be misleading. Hours are only meaningful while\n"
"    // actually discharging on battery; while charging or on USB, just the\n"
"    // percent (which live-tracks upward while charging too) is shown.\n"
"    var battEl = document.getElementById('batt-estimate-text');\n"
"    var banner = document.getElementById('batt-warn-banner');\n"
"    var battFill = document.getElementById('sb-batt-fill');\n"
"    var sbBatt = document.getElementById('sb-batt');\n"
"    if (data.charger.ok && data.battery.present === false) {\n"
"      // No cell connected -- the board runs from USB. Hide the status-bar gauge\n"
"      // entirely (no phantom %), and never show the low-battery banner. The text\n"
"      // still says \"No battery\" so the Dashboard cockpit's mirrored row shows it.\n"
"      if (sbBatt) sbBatt.style.display = 'none';\n"
"      setText('batt-estimate-text', 'No battery');\n"
"      battEl.style.color = '';\n"
"      banner.style.display = 'none';\n"
"    } else if (data.charger.ok) {\n"
"      if (sbBatt) sbBatt.style.display = '';\n"
"      var estText = Math.round(data.battery.percent) + '%';\n"
"      if (data.charger.on_battery && data.battery.hours_remaining >= 0) {\n"
"        estText += ' (~' + data.battery.hours_remaining.toFixed(1) + 'h left)';\n"
"      }\n"
"      if (data.battery.low_warning) estText += ' — LOW, charge soon';\n"
"      setText('batt-estimate-text', estText);\n"
"      battEl.style.color = data.battery.low_warning ? 'var(--red)' : '';\n"
"      // Status-bar battery glyph fill: width = %, colour reflects level/charging.\n"
"      if (battFill) {\n"
"        var pct = Math.max(0, Math.min(100, data.battery.percent));\n"
"        battFill.style.width = pct + '%';\n"
"        battFill.style.background = data.battery.low_warning ? 'var(--red)'\n"
"          : (pct <= 20 ? 'var(--yellow)' : 'var(--green)');\n"
"      }\n"
"      if (data.battery.low_warning) {\n"
"        banner.style.display = 'flex';\n"
"        var hr = data.battery.hours_remaining, left = '';\n"
"        if (data.charger.on_battery && hr >= 0) {\n"
"          var mins = Math.round(hr * 60);\n"
"          left = mins >= 60 ? (' — about ' + Math.floor(mins / 60) + ' h ' + (mins % 60) + ' min of runtime left')\n"
"                            : (' — about ' + mins + ' min of runtime left');\n"
"        }\n"
"        setText('batt-warn-text', 'Battery low' + left + '. The device keeps recording and will ' +\n"
"          'shut down safely on its own to protect the cell — plug in USB to keep going.');\n"
"      } else {\n"
"        banner.style.display = 'none';\n"
"      }\n"
"    } else {\n"
"      if (sbBatt) sbBatt.style.display = '';\n"
"      setText('batt-estimate-text', '-');\n"
"      battEl.style.color = '';\n"
"      banner.style.display = 'none';\n"
"    }\n"
"  }\n"
"\n"
"  if (data.wifi) {\n"
"    var connected = data.wifi.sta_state === 'connected';\n"
"    var stateLabel = connected ? ('connected (' + data.wifi.sta_ssid + ')' + (data.wifi.enterprise ? ' · enterprise' : ''))\n"
"      : (data.wifi.sta_state === 'idle' ? 'access point only' : 'searching…');\n"
"    setText('wifi-state', stateLabel);\n"
"    // Status-bar Wi-Fi signal bars + SSID + clock.\n"
"    setWifiBars(connected ? data.wifi.rssi : null);\n"
"    setText('sb-wifi-ssid', connected ? data.wifi.sta_ssid : (data.wifi.sta_state === 'idle' ? 'AP only' : '—'));\n"
"    var sbClock = document.getElementById('sb-clock');\n"
"    if (sbClock) {\n"
"      if (data.wifi.clock) {\n"
"        // \"2026-09-03 13:23:35\" -> \"13:23:35 UTC\"; green when NTP-synced.\n"
"        var tpart = (data.wifi.clock.split(' ')[1] || data.wifi.clock);\n"
"        sbClock.textContent = tpart + ' UTC' + (data.wifi.ntp_synced ? '' : ' ~');\n"
"        sbClock.style.color = data.wifi.ntp_synced ? 'var(--green)' : 'var(--yellow)';\n"
"        sbClock.title = data.wifi.ntp_synced ? 'Clock synced via NTP' : 'Clock set from the browser (NTP not synced)';\n"
"      } else {\n"
"        sbClock.textContent = 'no clock';\n"
"        sbClock.style.color = 'var(--faint)';\n"
"      }\n"
"    }\n"
"    setText('wifi-ip', data.wifi.ip || '-');\n"
"    setText('wifi-ntp', data.wifi.ntp_synced ? 'yes' : 'no');\n"
"    setText('wifi-time', data.wifi.clock\n"
"      ? (data.wifi.clock + ' UTC' + (data.wifi.ntp_synced ? '' : ' (via browser)'))\n"
"      : 'not set');\n"
"    var tsf = data.wifi.tsf_us;\n"
"    setText('wifi-tsf', (tsf && tsf > 0) ? (tsf.toLocaleString() + ' µs') : 'not synced (join an AP)');\n"
"    if (data.wifi.hostname) setText('wifi-host', data.wifi.hostname + '.local');\n"
"    if (data.wifi.ap_ssid) setText('wifi-ap', data.wifi.ap_ssid);\n"
"    var mf = document.getElementById('mdns-friendly');\n"
"    if (mf && document.activeElement !== mf) mf.checked = !!data.wifi.mdns_friendly;\n"
"    var re = document.getElementById('report-enabled');\n"
"    if (re && document.activeElement !== re) re.checked = !!data.wifi.report_enabled;\n"
"    // Access point card: current BSSID + pin state.\n"
"    lastWifi = data.wifi;\n"
"    setText('wifi-cur-bssid', data.wifi.bssid || (connected ? '–' : 'not connected'));\n"
"    var pinState = document.getElementById('wifi-pin-state');\n"
"    var unpinBtn = document.getElementById('ap-unpin-btn');\n"
"    if (data.wifi.pinned_bssid) {\n"
"      // BSSID itself is shown in \"Current AP\"; keep this value short so it never\n"
"      // clips on mobile. Flag when the pinned AP is out of reach (fallen back).\n"
"      var onPin = (data.wifi.bssid || '').toUpperCase() === data.wifi.pinned_bssid.toUpperCase();\n"
"      pinState.textContent = onPin ? 'Pinned' : 'Pinned · using another AP';\n"
"      pinState.style.color = onPin ? 'var(--accent)' : 'var(--yellow)';\n"
"      if (unpinBtn) unpinBtn.style.display = '';\n"
"    } else {\n"
"      pinState.textContent = 'Automatic (strongest)';\n"
"      pinState.style.color = '';\n"
"      if (unpinBtn) unpinBtn.style.display = 'none';\n"
"    }\n"
"    var failRow = document.getElementById('wifi-fail-row');\n"
"    // The reconnect task never \"gives up\" now, so there's no failed state;\n"
"    // show the last reason while it's searching (not connected) if we have one.\n"
"    if (!connected && data.wifi.sta_fail_reason) {\n"
"      setText('wifi-fail-reason', data.wifi.sta_fail_reason);\n"
"      failRow.style.display = '';\n"
"    } else {\n"
"      failRow.style.display = 'none';\n"
"    }\n"
"    renderSavedNetworks(data.wifi.saved || []);\n"
"    document.getElementById('wifi-txpower-row').style.display = data.wifi.tx_power_reduced ? '' : 'none';\n"
"    // NTP unreachable (no infra Wi-Fi, or no internet uplink from it) --\n"
"    // fall back to the browser's clock so recordings still get a real\n"
"    // timestamp instead of just a boot-relative counter. One attempt per\n"
"    // page load; the device ignores this once NTP has synced on its own.\n"
"    if (!data.wifi.ntp_synced && !browserTimeSynced) {\n"
"      browserTimeSynced = true;\n"
"      fetch('/api/time/set', {\n"
"        method: 'POST',\n"
"        headers: {'Content-Type': 'application/json'},\n"
"        body: JSON.stringify({unix_ms: Date.now()}),\n"
"      }).catch(function() {});\n"
"    }\n"
"  }\n"
"\n"
"  if (lastRecordingActive && data.recording && !data.recording.active) {\n"
"    refreshRecordings(); // a session just ended -- pick up its final size\n"
"  }\n"
"  if (data.recording) lastRecordingActive = data.recording.active;\n"
"}\n"
"\n"
"var liveCsv = null;\n"
"var lastRecordingActive = false;\n"
"var recordingsData = [];\n"
"var rowSlots = {};   // recording id -> its CSV-status <span>, updated live each poll\n"
"var openRecId = null; // id of the recording whose detail sheet is open, or null\n"
"var lastMarkerCount = -1;\n"
"var markerCache = [];      // last /api/record/markers result, for chip rendering + edit\n"
"var selectedMarkId = null; // marker currently open in the inline edit row, or null\n"
"var mkIsNew = false;       // the selected marker was just added (Delete reads \"Discard\")\n"
"var recSdFree = 0;         // last known SD free bytes, for the record readout's \"SD left\"\n"
"\n"
"// mm:ss (or h:mm:ss) for a marker's elapsed-seconds position.\n"
"function fmtMarkTime(s) {\n"
"  s = Math.max(0, Math.round(s));\n"
"  var h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60;\n"
"  var p = function(n) { return (n < 10 ? '0' : '') + n; };\n"
"  return h ? (h + ':' + p(m) + ':' + p(ss)) : (m + ':' + p(ss));\n"
"}\n"
"// Markers on the dashboard render as a single horizontal strip of chips (mockup\n"
"// style) -- clicking a chip opens the inline note/delete editor. The strip is\n"
"// one scrolling row, so adding marks never grows the panel / shrinks the graph.\n"
"var markerFetchedAt = 0;\n"
"// The current session's markers as {ago: seconds before now, label}, for chart lines.\n"
"function chartMarks() {\n"
"  if (!recordingActive || !markerCache.length) return [];\n"
"  var extra = (Date.now() - markerFetchedAt) / 1000;\n"
"  return markerCache.map(function (m, i) { return {ago: (m.ago_ms || 0) / 1000 + extra, label: '#' + (i + 1)}; });\n"
"}\n"
"function markById(id) {\n"
"  for (var i = 0; i < markerCache.length; i++) if (markerCache[i].id === id) return markerCache[i];\n"
"  return null;\n"
"}\n"
"function markerChipsHtml(marks) {\n"
"  var h = '';\n"
"  for (var i = 0; i < marks.length; i++) {\n"
"    var mk = marks[i];\n"
"    var note = '';\n"
"    if (mk.note) {\n"
"      var n = mk.note.length > 16 ? mk.note.slice(0, 16) + '…' : mk.note;\n"
"      note = ' \"' + escapeHtml(n) + '\"';\n"
"    }\n"
"    h += '<span class=\"mkchip' + (mk.id === selectedMarkId ? ' sel' : '') + '\" onclick=\"openMarkerEdit(' + mk.id + ')\">' +\n"
"         '<b>#' + (i + 1) + '</b> ' + fmtMarkTime(mk.t_s) + note + '</span>';\n"
"  }\n"
"  return h;\n"
"}\n"
"function renderMarkerChips() {\n"
"  var el = document.getElementById('marker-list');\n"
"  if (el) el.innerHTML = markerChipsHtml(markerCache);\n"
"}\n"
"function refreshMarkerList() {\n"
"  fetch('/api/record/markers').then(function(r) { return r.json(); }).then(function(marks) {\n"
"    markerCache = marks;\n"
"    markerFetchedAt = Date.now();\n"
"    renderMarkerChips();\n"
"    drawActivity(); drawMotion();\n"
"    // A selected marker that vanished (e.g. deleted elsewhere) closes the editor.\n"
"    if (selectedMarkId !== null && !markById(selectedMarkId)) closeMarkerEdit();\n"
"  }).catch(function() {});\n"
"}\n"
"function showMarkerEdit(mk) {\n"
"  document.getElementById('mkedit-lbl').textContent = 'Marker · ' + fmtMarkTime(mk.t_s);\n"
"  var inp = document.getElementById('marker-note');\n"
"  inp.value = mk.note || '';\n"
"  document.getElementById('mkedit-del').textContent = mkIsNew ? 'Discard' : 'Delete';\n"
"  document.getElementById('marker-edit').style.display = '';\n"
"  renderMarkerChips(); // re-highlight the selected chip\n"
"  inp.focus();\n"
"}\n"
"function openMarkerEdit(id) {\n"
"  var mk = markById(id);\n"
"  if (!mk) return;\n"
"  selectedMarkId = id;\n"
"  mkIsNew = false;\n"
"  showMarkerEdit(mk);\n"
"}\n"
"function closeMarkerEdit() {\n"
"  selectedMarkId = null;\n"
"  mkIsNew = false;\n"
"  var box = document.getElementById('marker-edit');\n"
"  if (box) box.style.display = 'none';\n"
"  renderMarkerChips();\n"
"}\n"
"function addMarker(btn) {\n"
"  btn.disabled = true;\n"
"  fetch('/api/record/mark', { method: 'POST' }).then(function(r) {\n"
"    return r.ok ? r.json() : null;\n"
"  }).then(function(res) {\n"
"    btn.disabled = false;\n"
"    if (!res) { toast('Could not add mark (not recording?)'); return; }\n"
"    selectedMarkId = res.id;\n"
"    mkIsNew = true;\n"
"    lastMarkerCount = -1; // force a status-driven refresh too\n"
"    // Pull the fresh list so the new chip appears, then open it for an optional note.\n"
"    fetch('/api/record/markers').then(function(r) { return r.json(); }).then(function(marks) {\n"
"      markerCache = marks;\n"
"      markerFetchedAt = Date.now();\n"
"      drawActivity(); drawMotion();\n"
"      showMarkerEdit(markById(res.id) || { id: res.id, t_s: 0, note: '' });\n"
"    }).catch(function() {});\n"
"  }).catch(function() { btn.disabled = false; });\n"
"}\n"
"// Silently drop the characters the firmware would otherwise replace in a marker\n"
"// note (double-quote and backslash). Length is capped by the input's maxlength,\n"
"// which matches the firmware's note buffer. Keeps the caret in place.\n"
"function noteFilter(el) {\n"
"  var v = el.value, cleaned = v.replace(/[\"\\\\]/g, '');\n"
"  if (cleaned === v) return;\n"
"  var pos = (v.slice(0, el.selectionStart || 0).replace(/[\"\\\\]/g, '')).length;\n"
"  el.value = cleaned;\n"
"  try { el.setSelectionRange(pos, pos); } catch (e) {}\n"
"}\n"
"function saveMarkerNote() {\n"
"  if (selectedMarkId === null) return;\n"
"  postJson('/api/record/mark/note', { id: selectedMarkId, note: document.getElementById('marker-note').value }, function() {});\n"
"  closeMarkerEdit();\n"
"  lastMarkerCount = -1;\n"
"  refreshMarkerList();\n"
"}\n"
"// Delete the marker open in the editor (labelled \"Discard\" for a just-added one).\n"
"function markerEditDelete() {\n"
"  if (selectedMarkId === null) return;\n"
"  postJson('/api/record/mark/delete', { id: selectedMarkId }, function() {});\n"
"  closeMarkerEdit();\n"
"  lastMarkerCount = -1;\n"
"  refreshMarkerList();\n"
"}\n"
"function toggleRecording() {\n"
"  if (recordingActive) stopRecording(); else startRecording();\n"
"}\n"
"// 4.31 M / 12.0 k / 843 -- compact sample count for the record readout.\n"
"function fmtCount(n) {\n"
"  if (n >= 1e6) return (n / 1e6).toFixed(2) + ' M';\n"
"  if (n >= 1e3) return (n / 1e3).toFixed(1) + ' k';\n"
"  return String(n);\n"
"}\n"
"function setButtonMark(cb) {\n"
"  postJson('/api/settings/button_mark', { enabled: cb.checked ? 1 : 0 }, function() {});\n"
"}\n"
"function setMdnsFriendly(cb) {\n"
"  postJson('/api/settings/mdns_friendly', { enabled: cb.checked ? 1 : 0 }, function() {\n"
"    toast(cb.checked ? 'This device now answers btscanner.local' : 'btscanner.local disabled on this device');\n"
"  });\n"
"}\n"
"function setReportEnabled(cb) {\n"
"  postJson('/api/settings/report_enabled', { enabled: cb.checked ? 1 : 0 }, function() {\n"
"    toast(cb.checked ? 'Status reporting enabled' : 'Status reporting disabled');\n"
"  });\n"
"}\n"
"var otaBusy = false;\n"
"var otaCloudErrShown = false;\n"
"var otaConfigured = false;  // server URL + client id + secret all stored\n"
"var otaServerError = false; // last check/download failed -> reveal the config card\n"
"\n"
"// The connection indicator tracks the /api/status poll -- an active request\n"
"// every second -- rather than the /ws socket, which can sit \"open\" for a long\n"
"// time after the device silently drops (no FIN seen), falsely showing \"live\".\n"
"var lastStatusOkAt = Date.now();\n"
"function setConnected(ok) {\n"
"  var dot = document.getElementById('live-dot');\n"
"  var txt = document.getElementById('live-text');\n"
"  if (!dot || !txt) return;\n"
"  if (ok) {\n"
"    dot.className = 'dot live';\n"
"    txt.textContent = 'live';\n"
"  } else if (Date.now() - lastStatusOkAt > 3500) {\n"
"    // Only after a few missed polls, so one hiccup on a marginal link doesn't flap it.\n"
"    dot.className = 'dot bad';\n"
"    txt.textContent = 'offline';\n"
"  }\n"
"}\n"
"// --- BLE device list -------------------------------------------------------\n"
"var bleAge = 60, bleSortKey = 'r', bleSortDir = -1, bleDevices = [], bleBusy = false;\n"
"// Bluetooth SIG company identifiers of the most common makers (rest shown as hex).\n"
"var BLE_COMPANIES = {0x0002:'Intel', 0x0006:'Microsoft', 0x000D:'Texas Instr.', 0x000F:'Broadcom',\n"
"  0x004C:'Apple', 0x0059:'Nordic', 0x006B:'Polar', 0x0075:'Samsung', 0x0087:'Garmin', 0x009E:'Bose',\n"
"  0x00C4:'LG', 0x00E0:'Google', 0x012D:'Sony', 0x0171:'Amazon', 0x027D:'Huawei', 0x02E5:'Espressif',\n"
"  0x038F:'Xiaomi'};\n"
"function bleMaker(m) {\n"
"  if (m < 0) return '';\n"
"  return BLE_COMPANIES[m] || ('0x' + ('000' + m.toString(16).toUpperCase()).slice(-4));\n"
"}\n"
"function bleAgeStr(ms) {\n"
"  if (ms < 1500) return 'now';\n"
"  var s = Math.round(ms / 1000);\n"
"  if (s < 90) return s + ' s';\n"
"  if (s < 5400) return Math.round(s / 60) + ' min';\n"
"  return Math.round(s / 3600) + ' h';\n"
"}\n"
"function bleKind(d) {\n"
"  var t = d.k === 'random-static' ? 'static' : d.k;\n"
"  var bits = [];\n"
"  if (d.p & 1) bits.push('conn');\n"
"  if (!(d.p & 16)) bits.push('ext');\n"
"  if (d.ph & 4) bits.push('coded');\n"
"  return t + (bits.length ? ' · ' + bits.join(' ') : '');\n"
"}\n"
"function bleSortBy(k) {\n"
"  if (bleSortKey === k) bleSortDir = -bleSortDir;\n"
"  else { bleSortKey = k; bleSortDir = (k === 'n' || k === 'a' || k === 'm' || k === 'p' || k === 'l') ? 1 : -1; }\n"
"  bleRender();\n"
"}\n"
"function bleRender() {\n"
"  var q = (document.getElementById('ble-filter').value || '').trim().toLowerCase();\n"
"  var list = bleDevices.filter(function(d) {\n"
"    if (!q) return true;\n"
"    return (d.n + ' ' + d.a + ' ' + bleMaker(d.m)).toLowerCase().indexOf(q) >= 0;\n"
"  });\n"
"  var k = bleSortKey, dir = bleSortDir;\n"
"  list.sort(function(x, y) {\n"
"    if (y.tg !== x.tg) return y.tg - x.tg; // targets always on top\n"
"    var a = x[k], b = y[k];\n"
"    if (k === 'n') { a = x.n || '￿'; b = y.n || '￿'; } // unnamed last\n"
"    if (k === 'm') { a = bleMaker(x.m) || '￿'; b = bleMaker(y.m) || '￿'; }\n"
"    if (k === 'p') { a = bleKind(x); b = bleKind(y); }\n"
"    if (a < b) return -dir;\n"
"    if (a > b) return dir;\n"
"    return x.a < y.a ? -1 : 1;\n"
"  });\n"
"  var ths = document.querySelectorAll('table.ble th');\n"
"  for (var i = 0; i < ths.length; i++) {\n"
"    var hk = ths[i].getAttribute('data-k');\n"
"    ths[i].textContent = ths[i].textContent.replace(/ [▲▼]$/, '') + (hk === k ? (dir > 0 ? ' ▲' : ' ▼') : '');\n"
"  }\n"
"  var html = [];\n"
"  for (var j = 0; j < list.length; j++) {\n"
"    var d = list[j];\n"
"    var pct = Math.max(0, Math.min(100, (d.r + 100) * 100 / 70)); // -100..-30 dBm\n"
"    html.push('<tr class=\"' + (d.tg ? 'tg' : '') + (d.l > 10000 ? ' stale' : '') + '\" onclick=\"bleOpen(\\'' + d.a + '\\',' + d.t + ')\" title=\"Open in Analyze\">' +\n"
"      '<td>' + (d.n ? escapeHtml(d.n) : '<span style=\"color:var(--faint)\">–</span>') + '</td>' +\n"
"      '<td class=\"mono\">' + d.a + '</td>' +\n"
"      '<td class=\"num mono\">' + d.r + '<span class=\"rbar\"><i style=\"width:' + pct.toFixed(0) + '%\"></i></span></td>' +\n"
"      '<td class=\"num mono\">' + d.ra.toFixed(0) + '</td>' +\n"
"      '<td class=\"num mono\">' + d.ps + '</td>' +\n"
"      '<td class=\"num mono\">' + d.c + '</td>' +\n"
"      '<td class=\"num mono\">' + bleAgeStr(d.l) + '</td>' +\n"
"      '<td>' + escapeHtml(bleMaker(d.m)) + '</td>' +\n"
"      '<td style=\"color:var(--muted)\">' + bleKind(d) + '</td></tr>');\n"
"  }\n"
"  document.getElementById('ble-body').innerHTML = html.join('');\n"
"  var empty = document.getElementById('ble-empty');\n"
"  empty.style.display = list.length ? 'none' : '';\n"
"  if (!list.length) empty.textContent = bleDevices.length ? 'No device matches the filter.' : 'No devices seen in this time window yet.';\n"
"}\n"
"function pollBle() {\n"
"  var tab = document.getElementById('tab-dashboard'), an = document.getElementById('tab-analyze');\n"
"  var visible = (tab && tab.classList.contains('active')) || (an && an.classList.contains('active'));\n"
"  if (bleBusy || otaBusy || !visible || document.hidden) return;\n"
"  bleBusy = true;\n"
"  fetch('/api/ble/devices?age=' + bleAge).then(function(r) { return r.json(); }).then(function(j) {\n"
"    bleBusy = false;\n"
"    bleDevices = j.devices || [];\n"
"    bleRender();\n"
"    renderTargets();\n"
"    anFill();\n"
"  }).catch(function() { bleBusy = false; });\n"
"}\n"
"function updateBleStatus(b) {\n"
"  var pill = document.getElementById('ble-pill');\n"
"  var cls = !b.ok ? 'bad' : b.scanning ? 'ok' : 'warn';\n"
"  var txt = !b.ok ? 'off' : b.scanning ? ('scanning · ' + (b.active ? 'active' : 'passive')) : 'stopped';\n"
"  pill.className = 'pill ' + cls; pill.textContent = txt;\n"
"  setText('ds-ble-rate', b.rps + ' /s · ' + b.recent + ' devices');\n"
"  setText('ds-ble-drops', String(b.drops));\n"
"  setText('ble-summary', b.recent + ' devices in the last minute · ' + b.rps + ' reports/s');\n"
"  setText('bs-state', !b.ok ? ('not running' + (b.err ? ' (error ' + b.err + ')' : '')) :\n"
"    (b.scanning ? 'scanning' : 'stopped') + ' · ' + (b.active ? 'active' : 'passive') + ' · ' + (b.coded ? '1M + Coded' : '1M'));\n"
"  setText('bs-total', String(b.total));\n"
"  setText('bs-drops', String(b.drops));\n"
"  setText('bs-restarts', String(b.restarts));\n"
"  setText('bs-devices', b.devices + (b.purges ? ' (' + b.purges + ' purges of old entries)' : ''));\n"
"  var a = document.getElementById('ble-active');\n"
"  if (a && document.activeElement !== a) a.checked = !!b.active;\n"
"  var c = document.getElementById('ble-coded');\n"
"  if (c && document.activeElement !== c) c.checked = !!b.coded;\n"
"}\n"
"function setBleConfig(key, cb) {\n"
"  var o = {}; o[key] = cb.checked ? 1 : 0;\n"
"  postJson('/api/ble/config', o, function() {});\n"
"}\n"
"setInterval(pollBle, 2000);\n"
"\n"
"function poll() {\n"
"  if (otaBusy) return; // don't pile up requests behind an in-progress firmware upload\n"
"  fetch('/api/status').then(function(r) { return r.json(); }).then(function(data) {\n"
"    lastStatusOkAt = Date.now();\n"
"    setConnected(true);\n"
"    update(data);\n"
"  }).catch(function() { setConnected(false); });\n"
"}\n"
"\n"
"function uploadFirmware(input) {\n"
"  var file = input.files && input.files[0];\n"
"  input.value = ''; // let the same file be re-picked later\n"
"  uploadFirmwareFile(file);\n"
"}\n"
"function uploadFirmwareFile(file) {\n"
"  if (!file) return;\n"
"  if (otaBusy) return;\n"
"  if (!confirm('Update firmware with \"' + file.name + '\" (' + fmtBytesShort(file.size) +\n"
"               ')?\\n\\nThe device verifies it and reboots. Do NOT update during a recording.')) {\n"
"    return;\n"
"  }\n"
"  otaBusy = true;\n"
"  var prog = document.getElementById('ota-progress');\n"
"  var stat = document.getElementById('ota-status');\n"
"  prog.style.display = ''; prog.value = 0;\n"
"  stat.textContent = 'Uploading…';\n"
"  var xhr = new XMLHttpRequest();\n"
"  xhr.open('POST', '/api/ota/upload');\n"
"  xhr.upload.onprogress = function(e) {\n"
"    if (e.lengthComputable) {\n"
"      var pct = Math.round(e.loaded / e.total * 100);\n"
"      prog.value = pct;\n"
"      stat.textContent = 'Uploading & writing to flash — ' + pct + '%';\n"
"    }\n"
"  };\n"
"  xhr.onload = function() {\n"
"    if (xhr.status === 200) {\n"
"      prog.value = 100;\n"
"      stat.textContent = 'Update written — rebooting into the new firmware…';\n"
"      setTimeout(waitForReboot, 3000);\n"
"    } else {\n"
"      otaBusy = false;\n"
"      prog.style.display = 'none';\n"
"      stat.textContent = 'Update failed: ' + (xhr.responseText || ('HTTP ' + xhr.status));\n"
"    }\n"
"  };\n"
"  xhr.onerror = function() {\n"
"    // A dropped connection at the very end can mean the device already rebooted.\n"
"    stat.textContent = 'Connection lost — checking if the device rebooted…';\n"
"    setTimeout(waitForReboot, 3000);\n"
"  };\n"
"  xhr.send(file);\n"
"}\n"
"// --- Internet updates (check / install from the configured server) ----------\n"
"function updateCloudInstall(ota) {\n"
"  var prog = document.getElementById('ota-progress');\n"
"  var stat = document.getElementById('ota-status');\n"
"  var inst = document.getElementById('ota-install');\n"
"  if (ota.cloud_active && ota.state === 2) {        // downloaded + verified -> rebooting\n"
"    otaBusy = true;                                 // hand over to waitForReboot\n"
"    prog.style.display = ''; prog.value = 100;\n"
"    stat.textContent = 'Update installed — rebooting into the new firmware…';\n"
"    setTimeout(waitForReboot, 2000);\n"
"  } else if (ota.cloud_active) {\n"
"    prog.style.display = '';\n"
"    if (ota.state === 1 && ota.total > 0) {         // OTA_WRITING with a known size\n"
"      var pct = Math.round(ota.bytes / ota.total * 100);\n"
"      prog.value = pct;\n"
"      stat.textContent = 'Downloading & installing update — ' + pct + '%';\n"
"    } else {\n"
"      prog.value = 0;\n"
"      stat.textContent = 'Contacting update server…';\n"
"    }\n"
"    if (inst) inst.disabled = true;\n"
"  } else if (ota.cloud_error && !otaCloudErrShown) {\n"
"    otaCloudErrShown = true;\n"
"    otaServerError = true; refreshServerCard();\n"
"    prog.style.display = 'none';\n"
"    stat.textContent = 'Update failed: ' + ota.cloud_error;\n"
"    if (inst) inst.disabled = false;\n"
"  }\n"
"}\n"
"function checkForUpdate() {\n"
"  var btn = document.getElementById('ota-check');\n"
"  var res = document.getElementById('ota-check-result');\n"
"  var inst = document.getElementById('ota-install');\n"
"  btn.disabled = true; btn.textContent = 'Checking…';\n"
"  inst.style.display = 'none';\n"
"  res.style.display = ''; res.style.color = ''; res.textContent = 'Contacting update server…';\n"
"  fetch('/api/ota/check', { method: 'POST' }).then(function(r) { return r.json(); }).then(function(d) {\n"
"    btn.textContent = 'Check for updates';\n"
"    if (d.error) {\n"
"      otaServerError = true; refreshServerCard();\n"
"      res.style.color = 'var(--yellow)';\n"
"      res.textContent = d.configured ? ('Check failed: ' + d.error)\n"
"                                     : (d.error + ' — set it under “Update server” below.');\n"
"    } else if (d.available) {\n"
"      otaServerError = false; refreshServerCard();\n"
"      res.style.color = '';\n"
"      res.textContent = 'Update available: ' + d.latest + ' (' + fmtBytesShort(d.size) +\n"
"                        '). Running ' + d.current + '.';\n"
"      document.getElementById('ota-latest').textContent = d.latest;\n"
"      inst.style.display = '';\n"
"    } else {\n"
"      otaServerError = false; refreshServerCard();\n"
"      res.style.color = '';\n"
"      res.textContent = 'You’re on the latest version (' + d.current + ').';\n"
"    }\n"
"  }).catch(function() {\n"
"    btn.textContent = 'Check for updates';\n"
"    otaServerError = true; refreshServerCard();\n"
"    res.style.color = 'var(--yellow)'; res.textContent = 'Check failed (network error).';\n"
"  });\n"
"}\n"
"function installCloudUpdate() {\n"
"  if (!confirm('Download and install the new firmware now?\\n\\n' +\n"
"               'The device verifies it and reboots. Do NOT update during a recording.')) return;\n"
"  otaCloudErrShown = false;\n"
"  var inst = document.getElementById('ota-install');\n"
"  inst.disabled = true;\n"
"  var prog = document.getElementById('ota-progress');\n"
"  var stat = document.getElementById('ota-status');\n"
"  prog.style.display = ''; prog.value = 0;\n"
"  stat.textContent = 'Starting update…';\n"
"  fetch('/api/ota/install', { method: 'POST' }).then(function(r) {\n"
"    if (!r.ok) return r.text().then(function(t) { throw new Error(t || ('HTTP ' + r.status)); });\n"
"    // Success: progress + reboot are driven by poll() -> updateCloudInstall().\n"
"  }).catch(function(e) {\n"
"    inst.disabled = false;\n"
"    prog.style.display = 'none';\n"
"    stat.textContent = 'Update failed: ' + e.message;\n"
"  });\n"
"}\n"
"// The config card is only shown when it's needed: nothing is set up yet, or the\n"
"// last check/download failed (so the credentials are the likely fix).\n"
"function refreshServerCard() {\n"
"  var c = document.getElementById('ota-server-card');\n"
"  if (c) c.style.display = (!otaConfigured || otaServerError) ? '' : 'none';\n"
"}\n"
"function loadUpdateServer(done) {\n"
"  fetch('/api/ota/server').then(function(r) { return r.json(); }).then(function(d) {\n"
"    document.getElementById('ota-url').value = d.url || '';\n"
"    document.getElementById('ota-cfid').value = d.client_id || '';\n"
"    document.getElementById('ota-cfsecret').placeholder =\n"
"      d.has_secret ? 'saved — leave blank to keep it' : 'CF-Access client secret';\n"
"    otaConfigured = !!(d.url && d.client_id && d.has_secret);\n"
"    if (done) done();\n"
"  }).catch(function() { if (done) done(); });\n"
"}\n"
"// Forgives the two common paste mistakes: a base URL with a trailing slash\n"
"// (which would double into \"//version\" -> 404) and a token copied with its\n"
"// header label (\"CF-Access-Client-Id: <id>\"). The device sanitizes these too;\n"
"// this just reflects the cleaned value back in the field. Mirrors ota_cloud.c.\n"
"function cleanOtaValue(v, isUrl) {\n"
"  v = (v || '').trim();\n"
"  return isUrl ? v.replace(/\\/+$/, '') : v.replace(/^[A-Za-z0-9-]+:\\s*/, '').trim();\n"
"}\n"
"function cleanOtaField(el, isUrl) { el.value = cleanOtaValue(el.value, isUrl); }\n"
"function saveUpdateServer() {\n"
"  var status = document.getElementById('ota-server-status');\n"
"  status.style.color = ''; status.textContent = 'Saving…';\n"
"  var body = {\n"
"    url: cleanOtaValue(document.getElementById('ota-url').value, true),\n"
"    client_id: cleanOtaValue(document.getElementById('ota-cfid').value, false),\n"
"    client_secret: cleanOtaValue(document.getElementById('ota-cfsecret').value, false)\n"
"  };\n"
"  fetch('/api/ota/server', {\n"
"    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)\n"
"  }).then(function(r) {\n"
"    if (!r.ok) return r.text().then(function(t) { throw new Error(t || ('HTTP ' + r.status)); });\n"
"    status.style.color = 'var(--green)'; status.textContent = 'Saved.';\n"
"    document.getElementById('ota-cfsecret').value = '';\n"
"    otaServerError = false; // assume the new details are good until a check says otherwise\n"
"    // Re-read config, then re-evaluate visibility after a beat so \"Saved.\" shows.\n"
"    loadUpdateServer(function() { setTimeout(refreshServerCard, 1500); });\n"
"  }).catch(function(e) {\n"
"    status.style.color = 'var(--yellow)'; status.textContent = 'Save failed: ' + e.message;\n"
"  });\n"
"}\n"
"function waitForReboot() {\n"
"  var stat = document.getElementById('ota-status');\n"
"  stat.textContent = 'Rebooting — reconnecting…';\n"
"  var tries = 0;\n"
"  var iv = setInterval(function() {\n"
"    tries++;\n"
"    fetch('/api/status', { cache: 'no-store' }).then(function(r) {\n"
"      if (r.ok) {\n"
"        clearInterval(iv);\n"
"        stat.textContent = 'Updated — reloading…';\n"
"        setTimeout(function() { location.reload(); }, 800);\n"
"      }\n"
"    }).catch(function() {});\n"
"    if (tries > 60) {\n"
"      clearInterval(iv);\n"
"      otaBusy = false;\n"
"      stat.textContent = 'Reconnect timed out — reload the page manually.';\n"
"    }\n"
"  }, 2000);\n"
"}\n"
"\n"
"// --- Actions ---------------------------------------------------------------\n"
"\n"
"function postJson(path, obj, cb) {\n"
"  fetch(path, {\n"
"    method: 'POST',\n"
"    headers: obj !== null ? {'Content-Type': 'application/json'} : {},\n"
"    body: obj !== null ? JSON.stringify(obj) : undefined,\n"
"  }).then(function(r) {\n"
"    if (cb) cb(r.ok);\n"
"    poll();\n"
"  }).catch(function() { if (cb) cb(false); });\n"
"}\n"
"\n"
"var MO_PILL = {still: 'pending', moving: 'warn', walking: 'ok', unknown: 'pending'};\n"
"function updateMotion(m) {\n"
"  var pill = document.getElementById('mo-pill');\n"
"  if (pill) { pill.className = 'pill ' + (m.ok ? (MO_PILL[m.state] || 'pending') : 'bad'); pill.textContent = m.ok ? m.state : 'no sensor'; }\n"
"  setText('mo-act', m.ok ? (m.act * 1000).toFixed(0) + ' mg' + (m.peak ? ' · peak ' + (m.peak * 1000).toFixed(0) + ' mg' : '') : '–');\n"
"  setText('mo-steps', m.steps + (m.cad > 0 ? ' · ' + m.cad.toFixed(0) + ' /min' : ''));\n"
"  setText('mo-speed', (m.speed >= 0 ? m.speed.toFixed(2) + ' m/s' : (m.state === 'moving' ? 'not walking' : '–')) + ' · ' + m.dist.toFixed(0) + ' m');\n"
"  setText('mo-axis', m.axis >= 0 ? m.axis.toFixed(0) + '° ±180 · ' + Math.round(m.conf * 100) + ' % clear' : '–');\n"
"  setText('mo-tilt', m.ok ? m.tilt.toFixed(0) + '°' : '–');\n"
"  setText('mo-rate', m.rate_hz ? m.rate_hz.toFixed(2) + ' Hz' : '–');\n"
"  setText('mo-drop', String(m.dropped) + (m.mdrops ? ' · ' + m.mdrops + ' file rows' : ''));\n"
"  var r = document.getElementById('mo-range');\n"
"  if (r && document.activeElement !== r) r.value = String(m.range);\n"
"  var l = document.getElementById('mo-log');\n"
"  if (l && document.activeElement !== l) l.checked = !!m.log;\n"
"}\n"
"function setMotionConfig(key, v) {\n"
"  var o = {}; o[key] = v;\n"
"  postJson('/api/motion/config', o, function (ok) { if (!ok) toast('Could not change the motion setting'); });\n"
"}\n"
"\n"
"function accelSelfTest(btn) {\n"
"  btn.disabled = true;\n"
"  setText('selftest-result', 'running...');\n"
"  document.getElementById('selftest-result').style.color = 'var(--muted)';\n"
"  postJson('/api/accel/selftest', null, function(ok) {\n"
"    if (!ok) {\n"
"      btn.disabled = false;\n"
"      setText('selftest-result', 'unavailable (recording?)');\n"
"      document.getElementById('selftest-result').style.color = 'var(--red)';\n"
"    }\n"
"    // On success the running -> pass/fail transition is picked up by poll().\n"
"  });\n"
"}\n"
"\n"
"function startRecording() {\n"
"  var name = document.getElementById('rec-name').value;\n"
"  postJson('/api/record/start', {name: name}, function (ok) { if (ok) setTimeout(refreshRecordings, 1500); });\n"
"}\n"
"\n"
"function stopRecording() {\n"
"  postJson('/api/record/stop', null);\n"
"}\n"
"\n"
"function runBenchmark(btn) {\n"
"  btn.disabled = true;\n"
"  postJson('/api/sdbench/run', null, function() { btn.disabled = false; });\n"
"}\n"
"\n"
"function shipMode(btn) {\n"
"  if (!confirm('Enter ship mode now? This safely stops any recording, then cuts battery power.')) return;\n"
"  btn.disabled = true;\n"
"  postJson('/api/charger/ship', null, function() { btn.disabled = false; });\n"
"}\n"
"\n"
"// Fires the LED party animation on the device (~6 s). Disables the button for\n"
"// its duration so it isn't spammed.\n"
"function partyMode(btn) {\n"
"  btn.disabled = true;\n"
"  fetch('/api/party', { method: 'POST' })\n"
"    .then(function() { toast('🎉 Party mode — watch the LED!'); })\n"
"    .catch(function() { toast('Could not start party mode'); })\n"
"    .finally(function() { setTimeout(function() { btn.disabled = false; }, 6000); });\n"
"}\n"
"\n"
"// TEMPORARY: RGB LED colour tester (remove with the palette set). Throttled so\n"
"// dragging the picker doesn't flood the device; sends a trailing update so the\n"
"// final colour always lands. Uses a bare fetch (not postJson) to avoid a status\n"
"// poll per colour change.\n"
"var ledTestSendAt = 0, ledTestPending = null, ledTestTimer = null;\n"
"function ledTestSend(obj) {\n"
"  fetch('/api/led/test', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(obj) }).catch(function () {});\n"
"}\n"
"function ledTest(hex) {\n"
"  var r = parseInt(hex.substr(1, 2), 16), g = parseInt(hex.substr(3, 2), 16), b = parseInt(hex.substr(5, 2), 16);\n"
"  setText('led-test-val', hex + ' · rgb(' + r + ',' + g + ',' + b + ')');\n"
"  ledTestPending = { r: r, g: g, b: b };\n"
"  var now = Date.now();\n"
"  if (now - ledTestSendAt >= 120) {\n"
"    ledTestSendAt = now;\n"
"    ledTestSend(ledTestPending); ledTestPending = null;\n"
"  } else {\n"
"    clearTimeout(ledTestTimer);\n"
"    ledTestTimer = setTimeout(function () {\n"
"      if (ledTestPending) { ledTestSendAt = Date.now(); ledTestSend(ledTestPending); ledTestPending = null; }\n"
"    }, 130);\n"
"  }\n"
"}\n"
"function ledTestOff() {\n"
"  clearTimeout(ledTestTimer); ledTestPending = null;\n"
"  ledTestSend({ off: true });\n"
"}\n"
"\n"
"function chgSetTsIgnore(chk) {\n"
"  chk.disabled = true;\n"
"  postJson('/api/charger/ts_ignore', {ignore: chk.checked}, function() { chk.disabled = false; });\n"
"}\n"
"\n"
"function escapeHtml(s) {\n"
"  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\n"
"}\n"
"\n"
"// Renders the remembered-network list (most-recently-used first), with a\n"
"// connected / wrong-password badge and Connect (switch) / Forget buttons.\n"
"// Networks are addressed by index into savedNetworks to sidestep quoting.\n"
"function renderSavedNetworks(list) {\n"
"  savedNetworks = list;\n"
"  var body = document.getElementById('wifi-saved-body');\n"
"  if (!list.length) {\n"
"    body.innerHTML = '<div class=\"sub\">None saved yet.</div>';\n"
"    return;\n"
"  }\n"
"  var html = '';\n"
"  for (var i = 0; i < list.length; i++) {\n"
"    var n = list[i];\n"
"    var badge = n.connected ? '<span class=\"pill ok\" style=\"margin-left:6px\">connected</span>'\n"
"      : (n.auth_failed ? '<span class=\"pill bad\" style=\"margin-left:6px\">wrong password</span>' : '');\n"
"    html += '<div class=\"rec-row\">' +\n"
"            '<span class=\"rec-name\">' + escapeHtml(n.ssid) +\n"
"            (n.enterprise ? ' <span class=\"sub\">(enterprise)</span>' : '') + badge + '</span>' +\n"
"            '<span class=\"rec-actions\">';\n"
"    if (!n.connected) {\n"
"      html += '<button onclick=\"wifiSelect(' + i + ', this)\">Connect</button>';\n"
"    }\n"
"    html += '<button class=\"danger\" onclick=\"wifiForget(' + i + ', this)\">Forget</button>' +\n"
"            '</span></div>';\n"
"  }\n"
"  body.innerHTML = html;\n"
"}\n"
"\n"
"function wifiSelect(idx, btn) {\n"
"  var net = savedNetworks[idx];\n"
"  if (!net) return;\n"
"  btn.disabled = true;\n"
"  postJson('/api/wifi/select', {ssid: net.ssid}, function() {\n"
"    setTimeout(function() { btn.disabled = false; }, 1500);\n"
"  });\n"
"}\n"
"\n"
"function wifiForget(idx, btn) {\n"
"  var net = savedNetworks[idx];\n"
"  if (!net) return;\n"
"  if (!confirm('Forget \"' + net.ssid + '\"?\\nThe device disconnects from it if it is the active network.')) {\n"
"    return;\n"
"  }\n"
"  btn.disabled = true;\n"
"  postJson('/api/wifi/forget', {ssid: net.ssid}, function() { btn.disabled = false; });\n"
"}\n"
"\n"
"// --- Pin to a specific access point (see the \"Access point\" card) -----------\n"
"var lastWifi = null; // most recent data.wifi, for the current/pinned BSSID\n"
"\n"
"function apScan() {\n"
"  var el = document.getElementById('ap-list');\n"
"  el.style.display = '';\n"
"  el.innerHTML = '<div class=\"sub\">Scanning…</div>';\n"
"  fetch('/api/wifi/aps').then(function (r) { return r.json(); }).then(function (d) {\n"
"    apRender(d.aps || []);\n"
"  }).catch(function () {\n"
"    el.innerHTML = '<div class=\"sub\" style=\"color:var(--yellow)\">Scan failed — try again.</div>';\n"
"  });\n"
"}\n"
"\n"
"function apRender(aps) {\n"
"  var el = document.getElementById('ap-list');\n"
"  if (!aps.length) {\n"
"    el.innerHTML = '<div class=\"sub\">No access points found for this network.</div>';\n"
"    return;\n"
"  }\n"
"  var cur = (lastWifi && lastWifi.bssid) ? lastWifi.bssid.toUpperCase() : '';\n"
"  var pin = (lastWifi && lastWifi.pinned_bssid) ? lastWifi.pinned_bssid.toUpperCase() : '';\n"
"  var html = '';\n"
"  for (var i = 0; i < aps.length; i++) {\n"
"    var a = aps[i], b = (a.bssid || '').toUpperCase();\n"
"    var badges = '';\n"
"    if (b === cur) badges += ' <span class=\"pill ok\">connected</span>';\n"
"    if (b === pin) badges += ' <span class=\"pill\" style=\"background:var(--accent-2); color:var(--accent-hi); border:1px solid var(--accent)\">pinned</span>';\n"
"    html += '<div class=\"rec-row\">' +\n"
"              '<span class=\"rec-name\">' +\n"
"                '<span style=\"font-family:var(--mono)\">' + escapeHtml(a.bssid) + '</span>' + badges +\n"
"                '<span class=\"sub\" style=\"display:block; margin-top:2px\">ch ' + a.channel + ' · ' + a.rssi + ' dBm</span>' +\n"
"              '</span>' +\n"
"              '<span class=\"rec-actions\">' +\n"
"                (b === pin ? '<span class=\"sub\">in use</span>'\n"
"                  : '<button data-b=\"' + escapeHtml(a.bssid) + '\" data-s=\"' + escapeHtml(a.ssid) + '\" onclick=\"apPin(this)\">Pin</button>') +\n"
"              '</span>' +\n"
"            '</div>';\n"
"  }\n"
"  el.innerHTML = html;\n"
"}\n"
"\n"
"function apPin(btn) {\n"
"  var b = btn.getAttribute('data-b'), s = btn.getAttribute('data-s');\n"
"  btn.disabled = true; btn.textContent = 'Pinning…';\n"
"  postJson('/api/wifi/pin', {ssid: s, bssid: b}, function (ok) {\n"
"    toast(ok ? 'Pinned — reconnecting to that AP' : 'Could not set pin');\n"
"    if (ok) document.getElementById('ap-list').style.display = 'none';\n"
"    else { btn.disabled = false; btn.textContent = 'Pin'; }\n"
"  });\n"
"}\n"
"\n"
"function apClearPin() {\n"
"  postJson('/api/wifi/pin/clear', {}, function (ok) {\n"
"    toast(ok ? 'Back to automatic AP selection' : 'Failed');\n"
"  });\n"
"}\n"
"\n"
"function wifiConnect(btn) {\n"
"  var ssid = document.getElementById('wifi-ssid').value;\n"
"  var pass = document.getElementById('wifi-pass').value;\n"
"  var ent = document.getElementById('wifi-enterprise').checked;\n"
"  var user = document.getElementById('wifi-user').value;\n"
"  if (!ssid) return;\n"
"  if (ent && !user) { alert('Enter the enterprise username (identity) first.'); return; }\n"
"  btn.disabled = true;\n"
"  postJson('/api/wifi/connect', {ssid: ssid, password: pass, username: user, enterprise: ent},\n"
"           function() { btn.disabled = false; });\n"
"}\n"
"\n"
"// Reveals the username field + security note only for enterprise networks --\n"
"// a normal home network just needs SSID + shared-key password.\n"
"function wifiUpdateEnterprise() {\n"
"  var ent = document.getElementById('wifi-enterprise').checked;\n"
"  document.getElementById('wifi-user').style.display = ent ? '' : 'none';\n"
"  document.getElementById('wifi-enterprise-note').style.display = ent ? '' : 'none';\n"
"}\n"
"\n"
"function wifiTogglePass(btn) {\n"
"  var inp = document.getElementById('wifi-pass');\n"
"  if (inp.type === 'password') {\n"
"    inp.type = 'text';\n"
"    btn.textContent = 'Hide';\n"
"  } else {\n"
"    inp.type = 'password';\n"
"    btn.textContent = 'Show';\n"
"  }\n"
"}\n"
"\n"
"function wifiScan(btn) {\n"
"  btn.disabled = true;\n"
"  var original = btn.textContent;\n"
"  btn.textContent = 'Scanning...';\n"
"  fetch('/api/wifi/scan').then(function(r) { return r.json(); }).then(function(data) {\n"
"    var sel = document.getElementById('wifi-networks');\n"
"    var networks = data.networks || [];\n"
"    sel.innerHTML = '';\n"
"    var placeholder = document.createElement('option');\n"
"    placeholder.value = '';\n"
"    placeholder.textContent = networks.length ? ('-- ' + networks.length + ' network' + (networks.length === 1 ? '' : 's') + ' found --') : '-- no networks found --';\n"
"    sel.appendChild(placeholder);\n"
"    networks.forEach(function(n) {\n"
"      var opt = document.createElement('option');\n"
"      opt.value = n.ssid;\n"
"      opt.dataset.enterprise = n.enterprise ? '1' : '0';\n"
"      var tag = n.enterprise ? ', enterprise' : (n.secure ? '' : ', open');\n"
"      opt.textContent = n.ssid + ' (' + n.rssi + ' dBm' + tag + ')';\n"
"      sel.appendChild(opt);\n"
"    });\n"
"    sel.classList.add('show');\n"
"  }).catch(function() {\n"
"    alert('Wi-Fi scan failed.');\n"
"  }).finally(function() {\n"
"    btn.disabled = false;\n"
"    btn.textContent = original;\n"
"  });\n"
"}\n"
"\n"
"function wifiPickNetwork() {\n"
"  var sel = document.getElementById('wifi-networks');\n"
"  if (!sel.value) return;\n"
"  document.getElementById('wifi-ssid').value = sel.value;\n"
"  var opt = sel.options[sel.selectedIndex];\n"
"  var ent = opt && opt.dataset.enterprise === '1';\n"
"  document.getElementById('wifi-enterprise').checked = ent;\n"
"  wifiUpdateEnterprise();\n"
"  document.getElementById(ent ? 'wifi-user' : 'wifi-pass').focus();\n"
"}\n"
"\n"
"\n"
"\n"
"\n"
"function remountSd(btn) {\n"
"  btn.disabled = true;\n"
"  postJson('/api/sdcard/remount', null, function() { btn.disabled = false; refreshRecordings(); });\n"
"}\n"
"\n"
"function fmtBytesShort(n) {\n"
"  if (n < 1024*1024) return (n/1024).toFixed(0) + ' KB';\n"
"  if (n < 1024*1024*1024) return (n/1024/1024).toFixed(1) + ' MB';\n"
"  return (n/1024/1024/1024).toFixed(2) + ' GB';\n"
"}\n"
"\n"
"function fmtDur(s) {\n"
"  s = Math.max(0, Math.round(s));\n"
"  var h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60;\n"
"  var p = function(n) { return (n < 10 ? '0' : '') + n; };\n"
"  return h ? (h + ':' + p(m) + ':' + p(ss)) : (m + ':' + p(ss));\n"
"}\n"
"function refreshRecordings() {\n"
"  fetch('/api/recordings').then(function (r) { return r.json(); }).then(function (list) {\n"
"    recordingsData = list || [];\n"
"    renderSessions();\n"
"  }).catch(function () {\n"
"    document.getElementById('recordings-body').innerHTML = '<div class=\"sub\">Could not read the SD card.</div>';\n"
"  });\n"
"}\n"
"function recById(id) {\n"
"  for (var i = 0; i < recordingsData.length; i++) if (recordingsData[i].id === id) return recordingsData[i];\n"
"  return null;\n"
"}\n"
"// \"2026-11-26 12:07:05 UTC\" from the session's name (or its .log start).\n"
"function recDate(r) {\n"
"  var m = /^(\\d{4})-(\\d\\d)-(\\d\\d)_(\\d\\d)(\\d\\d)(\\d\\d)/.exec(r.id);\n"
"  if (m) return m[1] + '-' + m[2] + '-' + m[3] + ' ' + m[4] + ':' + m[5] + ':' + m[6] + ' UTC';\n"
"  if (r.start && r.start !== '-') return r.start.replace('T', ' ').replace('Z', ' UTC');\n"
"  return '';\n"
"}\n"
"// Friendly title: the session name if one was given, else the date, else the raw id.\n"
"function recTitle(r) {\n"
"  var tag = r.id.replace(/^log_\\d{5}_?/, '').replace(/^\\d{4}-\\d{2}-\\d{2}_\\d{6}_?/, '');\n"
"  return tag ? tag.replace(/_/g, ' ') : (recDate(r) || r.id);\n"
"}\n"
"function recSubDate(r, title) { var d = recDate(r); return (title === d) ? r.id : (d || r.id); }\n"
"function recFiles(r, motion) { return (r.files || []).filter(function (f) { return !!f.motion === motion; })\n"
"  .sort(function (a, b) { return a.name.length - b.name.length || (a.name < b.name ? -1 : 1); }); }\n"
"function recEndText(r) {\n"
"  if (r.active) return 'still logging';\n"
"  return {stop: 'stopped normally', full: 'SD card full', error: 'write error'}[r.end] ||\n"
"    'no end entry — power lost or reset (data up to the last ~5 s is intact)';\n"
"}\n"
"function healthHtml(r) {\n"
"  if (r.active) return '<span class=\"mini live\">● logging</span>';\n"
"  var out = '';\n"
"  if (r.end === 'error') out = '<span class=\"mini bad\">⚠ write error</span>';\n"
"  else if (r.end === 'full') out = '<span class=\"mini warn\">card full</span>';\n"
"  else if (!r.end && r.log) out = '<span class=\"mini warn\" title=\"No end entry in the .log — power was lost or the board reset. Data up to the last ~5 s is intact.\">⚠ ended abruptly</span>';\n"
"  var drops = (r.log_drops || 0) + (r.motion_drops || 0);\n"
"  if (drops > 0) out += (out ? ' ' : '') + '<span class=\"mini warn\">⚠ ' + drops + ' rows dropped</span>';\n"
"  if (!out && r.log) out = '<span class=\"mini ok\">✓ clean</span>';\n"
"  return out;\n"
"}\n"
"// A per-session seed so its \"cover\" is a stable visual fingerprint.\n"
"function coverSeed(s) {\n"
"  var h = 2166136261;\n"
"  for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }\n"
"  return h >>> 0;\n"
"}\n"
"function mulberry32(a) {\n"
"  return function () {\n"
"    a |= 0; a = a + 0x6D2B79F5 | 0;\n"
"    var t = Math.imul(a ^ a >>> 15, 1 | a);\n"
"    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n"
"    return ((t ^ t >>> 14) >>> 0) / 4294967296;\n"
"  };\n"
"}\n"
"// Concentric signal arcs (a radio \"ping\") in the VibraShock cover style.\n"
"function drawCover(cv, seed) {\n"
"  if (!cv || !cv.getContext) return;\n"
"  var dpr = window.devicePixelRatio || 1;\n"
"  var w = cv.clientWidth || 40, hh = cv.clientHeight || 40;\n"
"  cv.width = w * dpr; cv.height = hh * dpr;\n"
"  var ctx = cv.getContext('2d'); if (!ctx) return;\n"
"  ctx.scale(dpr, dpr);\n"
"  ctx.fillStyle = '#0d1420'; ctx.fillRect(0, 0, w, hh);\n"
"  var rnd = mulberry32(seed), cx = w * (0.25 + rnd() * 0.5), cy = hh * (0.3 + rnd() * 0.5);\n"
"  for (var i = 0; i < 6; i++) {\n"
"    var r = 4 + i * (w / 9) + rnd() * 3;\n"
"    ctx.strokeStyle = 'rgba(138,198,255,' + (0.95 - i * 0.14).toFixed(2) + ')';\n"
"    ctx.lineWidth = 1.6;\n"
"    ctx.beginPath(); ctx.arc(cx, cy, r, rnd() * 6.28, rnd() * 6.28 + 2 + rnd() * 3); ctx.stroke();\n"
"  }\n"
"  ctx.fillStyle = '#8ac6ff'; ctx.beginPath(); ctx.arc(cx, cy, 2.2, 0, 6.29); ctx.fill();\n"
"}\n"
"function recSubHtml(r, title) {\n"
"  var bits = ['<span>' + escapeHtml(recSubDate(r, title)) + '</span>'];\n"
"  if (r.dur_s) bits.push('<span>' + fmtDur(r.dur_s) + '</span>');\n"
"  if (r.rows) bits.push('<span>' + fmtCount(r.rows) + ' rows</span>');\n"
"  bits.push('<span>' + fmtBytesShort(r.bytes) + '</span>');\n"
"  bits.push(recFiles(r, true).length ? '<span class=\"csv-txt on\">motion ✓</span>' : '<span class=\"csv-txt\">no motion</span>');\n"
"  if (r.mark) bits.push('<span class=\"csv-txt on\">markers</span>');\n"
"  return bits.join('');\n"
"}\n"
"function renderSessions() {\n"
"  var body = document.getElementById('recordings-body');\n"
"  // Newest first: dated sessions (by their UTC timestamp name), then the\n"
"  // undated \"log_NNNNN\" ones (clock wasn't set) by sequence number.\n"
"  var key = function (r) { return (/^\\d{4}-/.test(r.id) ? '1' : '0') + r.id; };\n"
"  var list = recordingsData.slice().sort(function (a, b) { return key(a) < key(b) ? 1 : -1; });\n"
"  if (!list.length) { body.innerHTML = '<div class=\"sub\">No logging sessions on the card yet.</div>'; return; }\n"
"  body.innerHTML = '';\n"
"  list.forEach(function (r) {\n"
"    var title = recTitle(r);\n"
"    var row = document.createElement('div');\n"
"    row.className = 'song';\n"
"    row.innerHTML =\n"
"      '<canvas class=\"cover\" width=\"40\" height=\"40\"></canvas>' +\n"
"      '<div class=\"song-main\">' +\n"
"        '<div class=\"song-title\"><span class=\"nm\">' + escapeHtml(title) + '</span></div>' +\n"
"        '<div class=\"song-sub\">' + recSubHtml(r, title) + '</div>' +\n"
"      '</div>' +\n"
"      healthHtml(r) +\n"
"      '<button class=\"dots\" aria-label=\"Quick actions\">⋯</button>';\n"
"    row.addEventListener('click', function (e) {\n"
"      if (e.target.closest('.dots')) { openMenu(e.target.closest('.dots'), r); return; }\n"
"      openSheet(r);\n"
"    });\n"
"    body.appendChild(row);\n"
"    drawCover(row.querySelector('.cover'), coverSeed(r.id));\n"
"  });\n"
"  if (openRecId) { var or = recById(openRecId); if (or) renderSheet(or); }\n"
"}\n"
"\n"
"/* ---- quick-actions popover ---- */\n"
"var recMenu = document.getElementById('rec-menu');\n"
"function openMenu(btn, r) {\n"
"  var items = [{i: 'ℹ', t: 'Details', fn: function () { openSheet(r); }}];\n"
"  var scan = recFiles(r, false), mot = recFiles(r, true);\n"
"  if (scan.length) items.push({i: '⬇', t: 'Download scan log' + (scan.length > 1 ? ' (part 1)' : ''), fn: function () { dl(scan[0].name); }});\n"
"  if (mot.length) items.push({i: '⬇', t: 'Download motion (100 Hz)' + (mot.length > 1 ? ' (part 1)' : ''), fn: function () { dl(mot[0].name); }});\n"
"  if (!r.active) {\n"
"    items.push({i: '✎', t: 'Rename', fn: function () { renameSession(r.id); }});\n"
"    items.push({d: true});\n"
"    items.push({i: '🗑', t: 'Delete session', danger: true, fn: function () { deleteSession(r.id); }});\n"
"  }\n"
"  recMenu.innerHTML = '';\n"
"  items.forEach(function (it) {\n"
"    if (it.d) { var dv = document.createElement('div'); dv.className = 'mdiv'; recMenu.appendChild(dv); return; }\n"
"    var b = document.createElement('button');\n"
"    if (it.danger) b.className = 'danger';\n"
"    b.innerHTML = '<span class=\"gi\">' + it.i + '</span>' + it.t;\n"
"    b.addEventListener('click', function (ev) { ev.stopPropagation(); closeMenu(); it.fn(); });\n"
"    recMenu.appendChild(b);\n"
"  });\n"
"  var rect = btn.getBoundingClientRect();\n"
"  recMenu.classList.add('open');\n"
"  var mw = recMenu.offsetWidth, mh = recMenu.offsetHeight;\n"
"  var left = Math.min(rect.right - mw, window.innerWidth - mw - 8);\n"
"  var top = rect.bottom + 6;\n"
"  if (top + mh > window.innerHeight - 8) top = rect.top - mh - 6;\n"
"  recMenu.style.left = Math.max(8, left) + 'px';\n"
"  recMenu.style.top = Math.max(8, top) + 'px';\n"
"}\n"
"function closeMenu() { recMenu.classList.remove('open'); }\n"
"\n"
"/* ---- detail sheet ---- */\n"
"var recBackdrop = document.getElementById('rec-backdrop');\n"
"var recSheet = document.getElementById('rec-sheet');\n"
"function openSheet(r) { openRecId = r.id; renderSheet(r); recBackdrop.classList.add('open'); }\n"
"function closeSheet() { openRecId = null; recBackdrop.classList.remove('open'); }\n"
"function metaRow(k, v) { return '<div class=\"m\"><span class=\"mk\">' + k + '</span><span class=\"mv\">' + escapeHtml(v) + '</span></div>'; }\n"
"function fileRow(name, mid, label, title) {\n"
"  return '<div class=\"filerow\"><span class=\"fn\">' + escapeHtml(name) + '</span>' +\n"
"    '<span class=\"fs\">' + mid + '</span>' +\n"
"    '<a class=\"btnlink\" href=\"/api/download?file=' + encodeURIComponent(name) + '\" download' +\n"
"    (title ? ' title=\"' + title + '\"' : '') + '>' + label + '</a></div>';\n"
"}\n"
"function renderSheet(r) {\n"
"  var title = recTitle(r), id = escapeHtml(r.id).replace(/'/g, '&#39;');\n"
"  var files = '';\n"
"  recFiles(r, false).forEach(function (f, i, a) { files += fileRow(f.name, a.length > 1 ? 'scan log · part ' + (i + 1) : 'scan log', fmtBytesShort(f.bytes), 'Download'); });\n"
"  recFiles(r, true).forEach(function (f, i, a) { files += fileRow(f.name, a.length > 1 ? 'motion · part ' + (i + 1) : 'motion 100 Hz', fmtBytesShort(f.bytes), 'Download'); });\n"
"  if (r.mark) files += fileRow(r.id + '.mark', 'markers', 'Download');\n"
"  if (r.log) files += fileRow(r.id + '.log', 'events', 'Download');\n"
"  var drops = (r.log_drops || 0) + (r.motion_drops || 0);\n"
"  recSheet.innerHTML =\n"
"    '<div class=\"sheet-head\">' +\n"
"      '<canvas class=\"cover\" width=\"58\" height=\"58\"></canvas>' +\n"
"      '<div><h3>' + escapeHtml(title) + (healthHtml(r) ? ' ' + healthHtml(r) : '') + '</h3>' +\n"
"        '<div class=\"when\">' + escapeHtml(recDate(r) || r.id) + (r.dur_s ? ' · ' + fmtDur(r.dur_s) : '') + '</div></div>' +\n"
"      '<button class=\"sheet-x\" aria-label=\"Close\" onclick=\"closeSheet()\">×</button>' +\n"
"    '</div>' +\n"
"    '<div class=\"sheet-body\">' +\n"
"      '<div class=\"slabel\">Session</div>' +\n"
"      '<div class=\"meta\">' +\n"
"        metaRow('Started', recDate(r) || '—') + metaRow('Duration', r.dur_s ? fmtDur(r.dur_s) : '—') +\n"
"        metaRow('Rows', (r.rows || 0).toLocaleString()) + metaRow('Size', fmtBytesShort(r.bytes)) +\n"
"        metaRow('Motion samples', r.motion_rows ? r.motion_rows.toLocaleString() : (recFiles(r, true).length ? '—' : 'not logged')) +\n"
"        metaRow('Parts', String(r.parts || 1)) +\n"
"        metaRow('Dropped rows', r.log ? String(drops) : '—') + metaRow('Name', r.id) +\n"
"      '</div>' +\n"
"      '<div class=\"sub\" style=\"margin-top:6px\">' + escapeHtml(recEndText(r)) + '</div>' +\n"
"      (r.mark ? '<div class=\"slabel\">Markers</div><div id=\"sheet-markers\">loading…</div>' : '') +\n"
"      '<div class=\"slabel\">Files</div><div class=\"files\">' + files + '</div>' +\n"
"      '<div class=\"slabel\">Events (.log)</div><div class=\"logbox\" id=\"rec-logbox\">' + (r.log ? 'loading…' : '(no log)') + '</div>' +\n"
"      '<div class=\"sheet-actions\">' + (r.active ? '<span class=\"sub\">Stop logging to rename or delete this session.</span>' :\n"
"        '<button class=\"btn\" onclick=\"renameSession(\\'' + id + '\\')\">Rename</button>' +\n"
"        '<button class=\"btn danger\" onclick=\"deleteSession(\\'' + id + '\\')\">Delete session</button>') + '</div>' +\n"
"    '</div>';\n"
"  drawCover(recSheet.querySelector('.cover'), coverSeed(r.id));\n"
"  if (r.log) loadLog(r);\n"
"  if (r.mark) loadMarkers(r);\n"
"}\n"
"// <base>.mark: \"id,time_s,uptime_ms,unix_time_s,note\" (note quoted, may hold commas).\n"
"function parseMarkFile(text) {\n"
"  var out = [], lines = text.split('\\n');\n"
"  for (var i = 0; i < lines.length; i++) {\n"
"    var line = lines[i].replace(/\\r$/, '').trim();\n"
"    if (!line || /^id[,;]/.test(line)) continue;\n"
"    var cols = line.split(',');\n"
"    if (cols.length < 2) continue;\n"
"    var tv = parseFloat(cols[1]);\n"
"    if (isNaN(tv)) continue;\n"
"    var unix = cols.length > 3 ? parseInt(cols[3], 10) : NaN;\n"
"    var note = cols.length > 4 ? cols.slice(4).join(',').replace(/^\"|\"$/g, '') : '';\n"
"    out.push({t_s: tv, unix: isNaN(unix) ? 0 : unix, note: note});\n"
"  }\n"
"  return out;\n"
"}\n"
"function markerRowsHtml(marks) {\n"
"  if (!marks.length) return '<div class=\"sub\">No markers.</div>';\n"
"  return marks.map(function (mk, i) {\n"
"    var when = mk.unix ? new Date(mk.unix * 1000).toISOString().slice(11, 19) + ' UTC' : '';\n"
"    return '<div class=\"marker-row\"><span class=\"mt\">#' + (i + 1) + ' · ' + fmtMarkTime(mk.t_s) + '</span>' +\n"
"      '<span class=\"' + (mk.note ? 'mn' : 'mn empty') + '\">' + (mk.note ? escapeHtml(mk.note) : '(no note)') + '</span>' +\n"
"      (when ? '<span class=\"fs\" style=\"color:var(--muted)\">' + when + '</span>' : '') + '</div>';\n"
"  }).join('');\n"
"}\n"
"function loadMarkers(r) {\n"
"  var box = document.getElementById('sheet-markers');\n"
"  if (!box) return;\n"
"  fetch('/api/download?file=' + encodeURIComponent(r.id + '.mark'))\n"
"    .then(function (x) { if (!x.ok) throw new Error('HTTP ' + x.status); return x.text(); })\n"
"    .then(function (t) { if (box && openRecId === r.id) box.innerHTML = markerRowsHtml(parseMarkFile(t)); })\n"
"    .catch(function () { if (box && openRecId === r.id) box.textContent = '(could not load markers)'; });\n"
"}\n"
"function loadLog(r) {\n"
"  var box = document.getElementById('rec-logbox');\n"
"  fetch('/api/download?file=' + encodeURIComponent(r.id + '.log'))\n"
"    .then(function (x) { return x.ok ? x.text() : ''; })\n"
"    .then(function (t) { if (box && openRecId === r.id) box.textContent = (t || '').trim() || '(empty)'; })\n"
"    .catch(function () { if (box) box.textContent = '(could not load log)'; });\n"
"}\n"
"function dl(name) {\n"
"  var a = document.createElement('a');\n"
"  a.href = '/api/download?file=' + encodeURIComponent(name);\n"
"  a.download = '';\n"
"  document.body.appendChild(a); a.click(); document.body.removeChild(a);\n"
"}\n"
"function renameSession(id) {\n"
"  var name = prompt('New name for this session (letters, digits, - and _):', id);\n"
"  if (!name || name === id) return;\n"
"  postJson('/api/recordings/rename', {id: id, name: name}, function (ok) {\n"
"    toast(ok ? 'Renamed' : 'Rename failed (name taken or invalid?)');\n"
"    if (ok) closeSheet();\n"
"    refreshRecordings();\n"
"  });\n"
"}\n"
"function deleteSession(id) {\n"
"  if (!confirm('Delete session \"' + id + '\" and all its files from the SD card?')) return;\n"
"  postJson('/api/recordings/delete', {id: id}, function (ok) {\n"
"    toast(ok ? 'Deleted' : 'Delete failed');\n"
"    if (ok) closeSheet();\n"
"    refreshRecordings();\n"
"  });\n"
"}\n"
"\n"
"/* ---- toast + global dismissers ---- */\n"
"var recToastEl = document.getElementById('rec-toast'), recToastTimer;\n"
"function toast(msg) {\n"
"  recToastEl.textContent = msg; recToastEl.classList.add('show');\n"
"  clearTimeout(recToastTimer); recToastTimer = setTimeout(function() { recToastEl.classList.remove('show'); }, 2200);\n"
"}\n"
"document.addEventListener('click', function (e) { if (!e.target.closest('#rec-menu') && !e.target.closest('.dots')) closeMenu(); });\n"
"document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { closeSheet(); closeMenu(); } });\n"
"recBackdrop.addEventListener('click', function (e) { if (e.target === recBackdrop) closeSheet(); });\n"
"window.addEventListener('scroll', closeMenu, true);\n"
"refreshRecordings();\n"
"\n"
"// Drag-and-drop a firmware.bin onto the picker (same install path as the button).\n"
"// The window-level handlers stop the browser from navigating away on a stray drop.\n"
"window.addEventListener('dragover', function(e) { e.preventDefault(); });\n"
"window.addEventListener('drop', function(e) { e.preventDefault(); });\n"
"(function() {\n"
"  var dz = document.getElementById('ota-drop');\n"
"  if (!dz) return;\n"
"  var fileDisabled = function() { return document.getElementById('ota-file').disabled; };\n"
"  ['dragenter', 'dragover'].forEach(function(ev) {\n"
"    dz.addEventListener(ev, function(e) {\n"
"      e.preventDefault(); e.stopPropagation();\n"
"      if (!fileDisabled()) dz.classList.add('drop-hot');\n"
"    });\n"
"  });\n"
"  ['dragleave', 'dragend', 'drop'].forEach(function(ev) {\n"
"    dz.addEventListener(ev, function(e) { e.stopPropagation(); dz.classList.remove('drop-hot'); });\n"
"  });\n"
"  dz.addEventListener('drop', function(e) {\n"
"    e.preventDefault(); e.stopPropagation();\n"
"    if (fileDisabled()) return;\n"
"    var f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];\n"
"    if (f) uploadFirmwareFile(f);\n"
"  });\n"
"})();\n"
"loadUpdateServer(refreshServerCard);\n"
"setInterval(poll, 1000);\n"
"setInterval(function() { setConnected(false); }, 1000); // staleness watchdog: catches a hung fetch\n"
"poll();\n"
"\n"
"/* ===================== charts + BLE analyze ===================== */\n"
"\n"
"// Sizes a canvas to its box at device-pixel resolution; returns {ctx,w,h} in CSS px.\n"
"function chartCtx(id) {\n"
"  var c = document.getElementById(id);\n"
"  if (!c || !c.clientWidth) return null;\n"
"  var dpr = window.devicePixelRatio || 1, w = c.clientWidth, h = c.clientHeight;\n"
"  if (c.width !== Math.round(w * dpr) || c.height !== Math.round(h * dpr)) {\n"
"    c.width = Math.round(w * dpr); c.height = Math.round(h * dpr);\n"
"  }\n"
"  var ctx = c.getContext('2d');\n"
"  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n"
"  ctx.clearRect(0, 0, w, h);\n"
"  return {ctx: ctx, w: w, h: h};\n"
"}\n"
"function cssVar(n) { return getComputedStyle(document.documentElement).getPropertyValue(n).trim(); }\n"
"function niceMax(v) {\n"
"  if (v <= 5) return 5;\n"
"  var p = Math.pow(10, Math.floor(Math.log10(v))), m = v / p;\n"
"  return (m <= 1 ? 1 : m <= 2 ? 2 : m <= 5 ? 5 : 10) * p;\n"
"}\n"
"// Draws one or two series against a shared time axis (index = seconds, oldest first).\n"
"function drawLines(id, series, xLabelSec, marks) {\n"
"  var g = chartCtx(id);\n"
"  if (!g) return;\n"
"  var ctx = g.ctx, L = 34, R = 34, T = 8, B = 18, W = g.w - L - R, H = g.h - T - B;\n"
"  var n = 0; series.forEach(function (s) { n = Math.max(n, s.data.length); });\n"
"  ctx.font = '10.5px ' + cssVar('--ui');\n"
"  ctx.strokeStyle = cssVar('--border'); ctx.lineWidth = 1;\n"
"  for (var gi = 0; gi <= 4; gi++) {\n"
"    var gy = T + H * gi / 4;\n"
"    ctx.beginPath(); ctx.moveTo(L, gy + .5); ctx.lineTo(L + W, gy + .5); ctx.stroke();\n"
"  }\n"
"  ctx.fillStyle = cssVar('--faint');\n"
"  ctx.textAlign = 'center';\n"
"  var span = xLabelSec || n;\n"
"  for (var ti = 0; ti <= 4; ti++) {\n"
"    var secAgo = Math.round(span * (1 - ti / 4));\n"
"    ctx.fillText(secAgo ? ('-' + (secAgo >= 120 ? Math.round(secAgo / 60) + ' min' : secAgo + ' s')) : 'now', L + W * ti / 4, g.h - 4);\n"
"  }\n"
"  (marks || []).forEach(function (m) {\n"
"    if (m.ago < 0 || m.ago > span) return;\n"
"    var x = L + W * (1 - m.ago / span);\n"
"    ctx.save();\n"
"    ctx.strokeStyle = cssVar('--accent-hi'); ctx.setLineDash([3, 3]); ctx.lineWidth = 1;\n"
"    ctx.beginPath(); ctx.moveTo(x + .5, T); ctx.lineTo(x + .5, T + H); ctx.stroke();\n"
"    ctx.setLineDash([]); ctx.fillStyle = cssVar('--accent-hi'); ctx.textAlign = 'center';\n"
"    ctx.fillText(m.label, x, T + 9);\n"
"    ctx.restore();\n"
"  });\n"
"  series.forEach(function (s, si) {\n"
"    var lo = s.min != null ? s.min : 0, hi = s.max;\n"
"    if (hi == null) { hi = 0; s.data.forEach(function (v) { if (v != null && v > hi) hi = v; }); hi = niceMax(hi); }\n"
"    ctx.fillStyle = s.color; ctx.textAlign = si === 0 ? 'right' : 'left';\n"
"    ctx.fillText(String(hi), si === 0 ? L - 4 : L + W + 4, T + 9);\n"
"    ctx.fillText(String(lo), si === 0 ? L - 4 : L + W + 4, T + H);\n"
"    var x0 = L + W * (1 - s.data.length / Math.max(n, 1));\n"
"    var dx = W / Math.max(n - 1, 1);\n"
"    if (s.bars) {\n"
"      ctx.fillStyle = s.color;\n"
"      s.data.forEach(function (v, i) {\n"
"        if (!v) return;\n"
"        var bh = Math.min(1, (v - lo) / (hi - lo)) * H;\n"
"        ctx.fillRect(x0 + i * dx - Math.max(dx * .35, .5), T + H - bh, Math.max(dx * .7, 1), bh);\n"
"      });\n"
"      return;\n"
"    }\n"
"    ctx.strokeStyle = s.color; ctx.lineWidth = 1.6; ctx.beginPath();\n"
"    var pen = false;\n"
"    s.data.forEach(function (v, i) {\n"
"      if (v == null) { pen = false; return; }\n"
"      var y = T + H - Math.max(0, Math.min(1, (v - lo) / (hi - lo))) * H, x = x0 + i * dx;\n"
"      if (pen) ctx.lineTo(x, y); else ctx.moveTo(x, y);\n"
"      pen = true;\n"
"    });\n"
"    ctx.stroke();\n"
"  });\n"
"}\n"
"\n"
"var actHist = null, moHist = null;\n"
"function drawMotion() {\n"
"  if (!moHist) return;\n"
"  var act = moHist.act, spd = moHist.spd.map(function (v) { return v < 0 ? null : v / 100; });\n"
"  var amax = 0; act.forEach(function (v) { if (v > amax) amax = v; });\n"
"  drawLines('an-mo-chart', [\n"
"    {data: act, color: cssVar('--yellow'), min: 0, max: niceMax(Math.max(amax, 50))},\n"
"    {data: spd, color: cssVar('--green'), min: 0, max: 2.5}\n"
"  ], 600, chartMarks());\n"
"  var n = moHist.st.length, cnt = [0, 0, 0, 0];\n"
"  moHist.st.forEach(function (v) { cnt[v] = (cnt[v] || 0) + 1; });\n"
"  setText('an-mo-sum', n ? ('still ' + Math.round(cnt[1] * 100 / n) + ' % · moving ' + Math.round(cnt[2] * 100 / n) +\n"
"    ' % · walking ' + Math.round(cnt[3] * 100 / n) + ' %') : '');\n"
"}\n"
"function drawActivity() {\n"
"  if (!actHist) return;\n"
"  var series = [{data: actHist.rps, color: cssVar('--accent')}, {data: actHist.dev, color: cssVar('--green')}];\n"
"  drawLines('act-chart', series, 600, chartMarks());\n"
"  drawLines('an-act-chart', series, 600, chartMarks());\n"
"}\n"
"function pollHistory() {\n"
"  var d = document.getElementById('tab-dashboard'), a = document.getElementById('tab-analyze');\n"
"  if (document.hidden || otaBusy || !((d && d.classList.contains('active')) || (a && a.classList.contains('active')))) return;\n"
"  fetch('/api/ble/history').then(function (r) { return r.json(); }).then(function (j) { actHist = j; drawActivity(); }).catch(function () {});\n"
"  if (a && a.classList.contains('active')) {\n"
"    fetch('/api/motion/history').then(function (r) { return r.json(); }).then(function (j) { moHist = j; drawMotion(); }).catch(function () {});\n"
"  }\n"
"}\n"
"setInterval(pollHistory, 5000);\n"
"window.addEventListener('resize', function () { drawActivity(); drawMotion(); anDraw(); });\n"
"\n"
"// Target list on the Dashboard + the short rule summary.\n"
"function renderTargets() {\n"
"  var t = bleDevices.filter(function (d) { return d.tg; });\n"
"  setText('tg-count', t.length ? (t.length + ' seen') : 'none');\n"
"  var b = document.getElementById('tg-body');\n"
"  if (!b) return;\n"
"  if (!t.length) { b.innerHTML = '<div class=\"sub\">No target device seen in this time window.</div>'; return; }\n"
"  b.innerHTML = t.map(function (d) {\n"
"    return '<div class=\"row\" style=\"cursor:pointer\" onclick=\"bleOpen(\\'' + d.a + '\\',' + d.t + ')\"><span class=\"k\">' +\n"
"      escapeHtml(d.n || d.a) + '</span><span class=\"v\">' + d.r + ' dBm · ' + bleAgeStr(d.l) + '</span></div>';\n"
"  }).join('');\n"
"}\n"
"function loadTargets() {\n"
"  fetch('/api/targets').then(function (r) { return r.text(); }).then(function (t) {\n"
"    var ta = document.getElementById('tg-rules');\n"
"    if (ta && document.activeElement !== ta) ta.value = t;\n"
"    var short = t.split('\\n').map(function (l) { return l.trim(); }).filter(function (l) { return l && l[0] !== '#'; });\n"
"    setText('tg-rules-short', short.length ? short.join(', ') : 'none');\n"
"  }).catch(function () {});\n"
"}\n"
"function saveTargets(btn) {\n"
"  var text = document.getElementById('tg-rules').value;\n"
"  btn.disabled = true;\n"
"  fetch('/api/targets', {method: 'POST', headers: {'Content-Type': 'text/plain'}, body: text}).then(function (r) {\n"
"    return r.text().then(function (msg) { return {ok: r.ok, msg: msg}; });\n"
"  }).then(function (res) {\n"
"    btn.disabled = false;\n"
"    var m = document.getElementById('tg-msg');\n"
"    m.textContent = res.ok ? 'Saved.' : res.msg;\n"
"    m.style.color = res.ok ? 'var(--green)' : 'var(--red)';\n"
"    loadTargets();\n"
"  }).catch(function () { btn.disabled = false; });\n"
"}\n"
"function setLogConfig(key, cb) {\n"
"  var o = {}; o[key] = cb.checked ? 1 : 0;\n"
"  postJson('/api/log/config', o, function () {});\n"
"}\n"
"loadTargets();\n"
"\n"
"// --- Analyze: one device ---\n"
"var anDev = null, anData = null, anBusy = false;\n"
"function bleOpen(a, t) {\n"
"  anDev = {a: a, t: t};\n"
"  anData = null;\n"
"  goTab('analyze');\n"
"  anFill();\n"
"  pollDevice();\n"
"}\n"
"function anPick(v) {\n"
"  if (!v) { anDev = null; anData = null; anRender(); return; }\n"
"  var p = v.split('|');\n"
"  bleOpen(p[0], +p[1]);\n"
"}\n"
"// Keeps the picker in step with the device list (strongest first).\n"
"function anFill() {\n"
"  var sel = document.getElementById('an-dev-select');\n"
"  if (!sel || document.activeElement === sel) return;\n"
"  var list = bleDevices.slice().sort(function (x, y) { return (y.tg - x.tg) || (y.r - x.r); });\n"
"  var cur = anDev ? anDev.a + '|' + anDev.t : '';\n"
"  var h = ['<option value=\"\">— pick a device (or click one on the Dashboard) —</option>'];\n"
"  var found = false;\n"
"  list.forEach(function (d) {\n"
"    var v = d.a + '|' + d.t;\n"
"    if (v === cur) found = true;\n"
"    h.push('<option value=\"' + v + '\"' + (v === cur ? ' selected' : '') + '>' + escapeHtml((d.tg ? '★ ' : '') + (d.n || '(no name)') + ' — ' + d.a + ' · ' + d.r + ' dBm') + '</option>');\n"
"  });\n"
"  if (anDev && !found) h.push('<option value=\"' + cur + '\" selected>' + escapeHtml(anDev.a + ' (not seen recently)') + '</option>');\n"
"  sel.innerHTML = h.join('');\n"
"}\n"
"function pollDevice() {\n"
"  var a = document.getElementById('tab-analyze');\n"
"  if (!anDev || anBusy || document.hidden || !a || !a.classList.contains('active')) return;\n"
"  anBusy = true;\n"
"  fetch('/api/ble/device?a=' + anDev.a + '&t=' + anDev.t).then(function (r) { return r.ok ? r.json() : null; }).then(function (j) {\n"
"    anBusy = false;\n"
"    anData = j;\n"
"    anRender();\n"
"  }).catch(function () { anBusy = false; });\n"
"}\n"
"setInterval(pollDevice, 2000);\n"
"function hexSpaced(h) { return h ? h.replace(/(..)/g, '$1 ').trim() : '–'; }\n"
"function anRender() {\n"
"  var box = document.getElementById('an-dev'), empty = document.getElementById('an-dev-empty');\n"
"  if (!anDev) { box.style.display = 'none'; empty.style.display = ''; empty.textContent = 'Pick a device to see its details, raw payloads and signal history.'; anDraw(); return; }\n"
"  if (!anData) { box.style.display = 'none'; empty.style.display = ''; empty.textContent = 'This device isn\\'t in the device table (any more) — it may have changed its address.'; anDraw(); return; }\n"
"  var d = anData;\n"
"  box.style.display = ''; empty.style.display = 'none';\n"
"  setText('ad-name', d.n ? d.n + (d.nk === 1 ? ' (shortened)' : '') : '–');\n"
"  setText('ad-addr', d.a);\n"
"  setText('ad-kind', d.k + ({public: ' — fixed', 'random-static': ' — fixed until reboot', rpa: ' — rotates', nrpa: ' — rotates'}[d.k] || ''));\n"
"  setText('ad-maker', d.m >= 0 ? bleMaker(d.m) + ' (0x' + ('000' + d.m.toString(16).toUpperCase()).slice(-4) + ')' : '–');\n"
"  setText('ad-rssi', d.r + ' / ' + d.ra.toFixed(1) + ' dBm');\n"
"  setText('ad-rssi2', d.rn + ' / ' + d.rx + ' dBm');\n"
"  setText('ad-count', d.c + ' total · ' + d.ps + ' in the last second');\n"
"  setText('ad-seen', bleAgeStr(d.f) + ' ago / ' + bleAgeStr(d.l) + (d.l < 1500 ? '' : ' ago'));\n"
"  setText('ad-tx', d.tx === 127 ? '–' : d.tx + ' dBm');\n"
"  var pr = [];\n"
"  if (d.p & 1) pr.push('connectable'); if (d.p & 2) pr.push('scannable'); if (d.p & 4) pr.push('directed');\n"
"  if (d.p & 8) pr.push('scan responses'); pr.push(d.p & 16 ? 'legacy' : 'BLE 5 extended');\n"
"  var ph = []; if (d.ph & 1) ph.push('1M'); if (d.ph & 2) ph.push('2M'); if (d.ph & 4) ph.push('Coded');\n"
"  setText('ad-props', pr.join(', ') + (ph.length ? ' · PHY ' + ph.join('/') : ''));\n"
"  setText('ad-app', d.ap ? '0x' + ('000' + d.ap.toString(16).toUpperCase()).slice(-4) : '–');\n"
"  setText('ad-uuid', d.u ? '0x' + ('000' + d.u.toString(16).toUpperCase()).slice(-4) : '–');\n"
"  setText('ad-target', d.tg ? 'yes' : 'no');\n"
"  setText('ad-adv', hexSpaced(d.adv));\n"
"  setText('ad-rsp', hexSpaced(d.rsp));\n"
"  anDraw();\n"
"}\n"
"function anDraw() {\n"
"  if (!anData) { var g = chartCtx('an-rssi-chart'); return; }\n"
"  var cmax = 0; anData.hc.forEach(function (v) { if (v > cmax) cmax = v; });\n"
"  drawLines('an-rssi-chart', [\n"
"    {data: anData.hr, color: cssVar('--accent'), min: -100, max: -30},\n"
"    {data: anData.hc, color: cssVar('--panel3'), bars: true, min: 0, max: niceMax(cmax)}\n"
"  ], 120);\n"
"}\n"
"\n"
"/* ===== SPA nav ===== */\n"
"function goTab(name) {\n"
"  ['dashboard', 'analyze', 'recordings', 'settings'].forEach(function (t) {\n"
"    var p = document.getElementById('tab-' + t);\n"
"    if (p) p.classList.toggle('active', t === name);\n"
"  });\n"
"  var btns = document.querySelectorAll('[data-nav]');\n"
"  for (var i = 0; i < btns.length; i++) {\n"
"    btns[i].classList.toggle('active', btns[i].getAttribute('data-nav') === name);\n"
"  }\n"
"  if (name === 'dashboard' || name === 'analyze') {\n"
"    pollBle(); pollHistory();\n"
"    requestAnimationFrame(function () { drawActivity(); drawMotion(); anDraw(); });\n"
"  }\n"
"  if (name === 'analyze') { anFill(); pollDevice(); }\n"
"  if (name === 'recordings') refreshRecordings();\n"
"  if (name === 'settings') loadTargets();\n"
"}\n"
"(function () {\n"
"  var btns = document.querySelectorAll('[data-nav]');\n"
"  for (var i = 0; i < btns.length; i++) {\n"
"    (function (b) { b.addEventListener('click', function () { goTab(b.getAttribute('data-nav')); }); })(btns[i]);\n"
"  }\n"
"})();\n"
"function sSetGroup(g) {\n"
"  var cards = document.querySelectorAll('#tab-settings .card[data-sgroup]');\n"
"  for (var i = 0; i < cards.length; i++) {\n"
"    cards[i].classList.toggle('sg-hide', cards[i].getAttribute('data-sgroup') !== g);\n"
"  }\n"
"  var items = document.querySelectorAll('#tab-settings .sitem');\n"
"  for (var j = 0; j < items.length; j++) {\n"
"    items[j].classList.toggle('active', items[j].getAttribute('data-sg') === g);\n"
"  }\n"
"  if (typeof refreshServerCard === 'function') refreshServerCard();\n"
"}\n"
"sSetGroup('bluetooth');\n"
"goTab('dashboard');\n"
"\n"
"</script>\n"
"<script>\n"
"/* ---- dashboard Status panel mirror ----------------------------------------\n"
" * The live device values (battery, charger, SD, Wi-Fi, clock) each have one\n"
" * canonical element -- in the top status bar or the Settings cards -- that the\n"
" * existing status poll (update()) already keeps current. The Dashboard cockpit\n"
" * shows a summary of the same values; since an id can only exist once, this\n"
" * copies the canonical text into the cockpit's ds-* cells on a light interval.\n"
" * Purely additive: it reads existing elements, writes new ones, and never\n"
" * touches the poll/update path. -------------------------------------------- */\n"
"(function () {\n"
"  var MAP = [\n"
"    ['ds-batt', 'batt-estimate-text'],\n"
"    ['ds-chg', 'chg-status-text'],\n"
"    ['ds-sd', 'sd-status-text'],\n"
"    ['ds-wifi', 'wifi-state'],\n"
"    ['ds-clock', 'wifi-time']\n"
"  ];\n"
"  function mirror() {\n"
"    for (var i = 0; i < MAP.length; i++) {\n"
"      var dst = document.getElementById(MAP[i][0]);\n"
"      var src = document.getElementById(MAP[i][1]);\n"
"      if (dst && src) {\n"
"        var t = src.textContent;\n"
"        if (dst.textContent !== t) dst.textContent = t;\n"
"      }\n"
"    }\n"
"  }\n"
"  setInterval(mirror, 600);\n"
"  mirror();\n"
"})();\n"
"</script>\n"
"</body>\n"
"</html>\n"
;
